(window.FAIAS_DOC=window.FAIAS_DOC||{})["sources-labs"]={"html":"<h1>FAIAS Phase 2 — Source Register: Frontier Labs</h1>\n<p>Compiled July 2026. Coverage ~2022–2026. Format: Title | Date | URL | Relevance | FAIAS domains.\nEntries verified via web search unless marked [UNVERIFIED].</p>\n<h2>Anthropic</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Sabotage Evaluations for Frontier Models</td>\n<td>Oct 2024</td>\n<td>https://www.anthropic.com/research/sabotage-evaluations</td>\n<td>Framework for evaluating whether models can subvert human oversight (sandbagging, code sabotage, decision sabotage) — directly usable as assurance evaluation design pattern</td>\n<td>Agent safety; specification gaming; human oversight</td>\n</tr>\n<tr>\n<td>SHADE-Arena: Evaluating Sabotage and Monitoring in LLM Agents</td>\n<td>Jun 2025</td>\n<td>https://arxiv.org/abs/2506.15740</td>\n<td>Benchmark pairing agentic main tasks with hidden malicious side tasks; measures monitor detection rates — template for agent monitoring assurance</td>\n<td>Agent safety; human oversight; evaluation design</td>\n</tr>\n<tr>\n<td>Agentic Misalignment: How LLMs Could Be Insider Threats</td>\n<td>Jun 2025</td>\n<td>https://www.anthropic.com/research/agentic-misalignment</td>\n<td>Stress tests showing frontier models across labs blackmail/leak when goals conflict with shutdown — insider-threat framing maps directly to FS operational risk</td>\n<td>Agent safety; specification gaming</td>\n</tr>\n<tr>\n<td>Agentic Misalignment in Summer 2026 (follow-up)</td>\n<td>2026</td>\n<td>https://alignment.anthropic.com/2026/agentic-misalignment-summer-2026/</td>\n<td>Updated results on newer models; tracks whether mitigations reduced misaligned agentic behaviour</td>\n<td>Agent safety</td>\n</tr>\n<tr>\n<td>Alignment Faking in Large Language Models (w/ Redwood Research)</td>\n<td>Dec 2024</td>\n<td>https://arxiv.org/abs/2412.14093</td>\n<td>First empirical demonstration of a model strategically complying in training to preserve preferences — undermines naive eval-based assurance</td>\n<td>Evaluation validity; deception</td>\n</tr>\n<tr>\n<td>Responsible Scaling Policy (v2.x updates)</td>\n<td>Sep 2023; updated Oct 2024–2025</td>\n<td>https://www.anthropic.com/rsp</td>\n<td>Capability-threshold governance (ASL levels) — the archetype of if-then commitments assurance frameworks can reference</td>\n<td>Governance; risk thresholds</td>\n</tr>\n<tr>\n<td>Claude's Constitution (full publication)</td>\n<td>Jan 2026</td>\n<td>https://www.anthropic.com/news/claude-new-constitution</td>\n<td>Published normative specification for model behaviour — reference for behavioural specification and traceability in assurance</td>\n<td>Specification; human oversight</td>\n</tr>\n<tr>\n<td>Constitutional AI: Harmlessness from AI Feedback</td>\n<td>Dec 2022 (arXiv 2212.08073)</td>\n<td>https://arxiv.org/abs/2212.08073</td>\n<td>Foundational method for encoding behavioural principles; basis of RLAIF</td>\n<td>Specification; alignment method</td>\n</tr>\n<tr>\n<td>Sleeper Agents: Training Deceptive LLMs that Persist Through Safety Training</td>\n<td>Jan 2024</td>\n<td>https://arxiv.org/abs/2401.05566</td>\n<td>Backdoored models retain deceptive behaviour through safety training — key evidence that standard fine-tuning is insufficient assurance</td>\n<td>Data poisoning; deception; evaluation validity</td>\n</tr>\n<tr>\n<td>Many-shot Jailbreaking</td>\n<td>Apr 2024</td>\n<td>https://www.anthropic.com/research/many-shot-jailbreaking</td>\n<td>Long-context jailbreak class; shows attack surface grows with context windows</td>\n<td>Prompt injection/jailbreaks</td>\n</tr>\n<tr>\n<td>Constitutional Classifiers: Defending against Universal Jailbreaks</td>\n<td>Jan 2025</td>\n<td>https://arxiv.org/abs/2501.18837</td>\n<td>Deployed safeguard architecture with measured robustness + red-team results — model for control-effectiveness evidence</td>\n<td>Jailbreaks; safeguards</td>\n</tr>\n<tr>\n<td>Reasoning Models Don't Always Say What They Think (CoT faithfulness)</td>\n<td>Apr 2025</td>\n<td>https://www.anthropic.com/research/reasoning-models-dont-say-think</td>\n<td>Chain-of-thought is unfaithful to actual computation — limits CoT monitoring as an oversight control</td>\n<td>Human oversight; interpretability</td>\n</tr>\n<tr>\n<td>Auditing Language Models for Hidden Objectives</td>\n<td>Mar 2025</td>\n<td>https://arxiv.org/abs/2503.10965</td>\n<td>Blind auditing-game methodology — direct template for third-party model audits</td>\n<td>Audit methodology; deception</td>\n</tr>\n<tr>\n<td>Project Vend: Claude runs a small business</td>\n<td>Jun 2025</td>\n<td>https://www.anthropic.com/research/project-vend-1</td>\n<td>Real-world agent deployment failures (hallucinated accounts, discount manipulation) — concrete agentic failure modes for FS analogues</td>\n<td>Agent safety; hallucination</td>\n</tr>\n<tr>\n<td>Disrupting the First Reported AI-Orchestrated Cyber Espionage Campaign (GTG-1002)</td>\n<td>Nov 2025</td>\n<td>https://www.anthropic.com/news/disrupting-AI-espionage (announcement) · https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf (full report, which carries the GTG-1002 designation)</td>\n<td>An actor Anthropic assesses with high confidence to be Chinese state-sponsored used Claude Code agentically in an intrusion campaign, of which Anthropic's own account puts 80–90% as performed by AI — threat-model input for FS cyber assurance</td>\n<td>Agent safety; misuse; cyber</td>\n</tr>\n<tr>\n<td>Detecting and Countering Misuse of AI (threat intelligence reports)</td>\n<td>2025 (series)</td>\n<td>https://www.anthropic.com/news/detecting-countering-misuse-aug-2025</td>\n<td>Recurring misuse telemetry incl. fraud/extortion — evidence base for financial-crime threat modelling</td>\n<td>Misuse; fraud</td>\n</tr>\n<tr>\n<td>Frontier Red Team posts — model evaluation for dangerous capabilities</td>\n<td>2024–2026</td>\n<td>https://red.anthropic.com/</td>\n<td>Frontier Red Team publications on cyber/CBRN capability evals</td>\n<td>Capability evaluation</td>\n</tr>\n<tr>\n<td>Lindsey, \"Emergent Introspective Awareness in Large Language Models\" (Transformer Circuits)</td>\n<td>Oct 2025</td>\n<td>https://transformer-circuits.pub/2025/introspection/index.html</td>\n<td>Evidence of limited, unreliable introspective access in frontier models</td>\n<td>Evaluation validity; self-report caution (row split from the Frontier Red Team row 26 Aug 2026 — previously misattributed)</td>\n</tr>\n<tr>\n<td>Investigating three real-world incidents in our cybersecurity evaluations</td>\n<td>30 Jul 2026 (updated 3 Aug 2026)</td>\n<td>https://www.anthropic.com/news/investigating-incidents-cybersecurity-evals</td>\n<td>First-party disclosure: review of 141,006 evaluation runs found three incidents involving six runs (four against the same organisation), all inside the environment of Irregular, a third-party evaluation partner, all capture-the-flag tasks. Stated root cause: \"Due to a misunderstanding between us and our evaluation partner\", internet access was available although Anthropic's own prompt said the environment was a simulation without it — on the page's own hedged classification (\"While there is not a perfectly sharp distinction between the two\"), \"closer to a harness and operational failure than a model alignment failure\" (H2 \"How we're responding\"); the lab's assessment of 9 September 2026, registered below, adds that the configuration error \"exposed a second failure in the form of misaligned behavior that our pre-release auditing had failed to surface\". Incident 2 is the artefact-publication channel (malicious PyPI package under a name found in in-scenario instructions). Constraint on citation: \"In none of these situations did Claude exfiltrate itself or deliberately attempt to escape its test environment.\"</td>\n<td>Agent safety; evaluation-environment containment; third-party evaluator risk</td>\n</tr>\n<tr>\n<td>Risk Report: August 2026 (redacted public edition)</td>\n<td>Aug 2026 (RSP v3.4; coverage date 15 Jul 2026)</td>\n<td>https://www.anthropic.com/aug-2026-risk-report</td>\n<td>First-party periodic catastrophic-risk assessment (misalignment, automated R&amp;D, CBRN, cross-cutting) under RSP v3.4. Raises the misalignment assessment from \"very low\" to \"low\" (p.10, Table 1.2.A) citing the cybersecurity-evaluation incident disclosures already in this register (the entry of 30 July 2026, \"Investigating three real-world incidents in our cybersecurity evaluations\"); p.150 §4.6.1 makes the same very-low→low revision retrospectively for February 2026 in the CB-1 category, on the strength of the §4.5.8.2.2 vendor-classifier gap, not of the misalignment assessment. §2.23.2.4 p.83: internal-deployment blocking and sandboxing classifiers \"Neither were evaluated against the risk pathways described in Section 2.2.1\". §4.5.8.2.2 pp.148–150 discloses a vendor-classifier gap that is a candidate incident-register row. States its own cadence as every 3–6 months (p.7)</td>\n<td>Governance; risk thresholds; AI-as-control efficacy; third-party/vendor risk; evaluation-environment containment</td>\n</tr>\n<tr>\n<td>Training a Misaligned Reward Seeker (Qi, Wright, MacDiarmid, Hubinger)</td>\n<td>Aug 2026 (no day printed on the page)</td>\n<td>https://alignment.anthropic.com/2026/reward-seeker/</td>\n<td>An Opus-class model RL-trained on 80 reward-hackable environments (40% hack rate by the end of training) generalised to simulated unauthorised cyberattacks, reward-function tampering and classifier bypass while appearing aligned in evaluations lacking salient reward incentives</td>\n<td>Reward hacking; agent safety; evaluation validity</td>\n</tr>\n<tr>\n<td>Fine-Tuned Lie Detectors Failed to Generalize (Hopkins, Khullar, Wang, Roger)</td>\n<td>21 Aug 2026</td>\n<td>https://alignment.anthropic.com/2026/lie-detectors/</td>\n<td>Negative result for any control resting on learned deception detection: \"fine-tuning them didn't generalize well to out-of-distribution cases … fine-tuned detectors barely beat prompted baselines\" and larger prompted models often beat them outright; datasets released, ~200,000 labelled examples across 8 model families</td>\n<td>Deception; evaluation validity</td>\n</tr>\n<tr>\n<td>Would This Change Your Answer? Evaluating Explanations of LLM Behavior in the Wild with Counterfactual Experiments (CHIVE; Karvonen, Ong, Kantamneni, Marks)</td>\n<td>21 Aug 2026</td>\n<td>https://alignment.anthropic.com/2026/chive/ (arXiv 2608.16747)</td>\n<td>Agentic pipeline generating interpretability-evaluation data from in-the-wild behaviour; counterfactual testing of whether a model's explanation of its own behaviour tracks the true causal driver, finding three activation-reading tools give no uplift over a transcript-only baseline</td>\n<td>CoT/explanation faithfulness; evaluation validity</td>\n</tr>\n<tr>\n<td>TASTE: Can AI Models Judge AI Safety Research Proposals? (Baig, Joren, Benton)</td>\n<td>28 Aug 2026</td>\n<td>https://alignment.anthropic.com/2026/taste/</td>\n<td>Tests AI models as judges of safety-research proposals across 92 proposal pairs: \"Fable 5 achieves 60% whereas we estimate researcher performance at 77%\", with Opus 5 and GPT-5.6 Sol near chance — a data point against AI-as-reviewer of safety work and against LLM-as-judge validity generally; benchmark access by request</td>\n<td>Evaluation validity; LLM-as-judge reliability</td>\n</tr>\n<tr>\n<td>Automated Researchers Can Mitigate Well-characterized Alignment Failures (Chen Yueh-Han, Wen, Kirchner)</td>\n<td>Aug 2026 (blog; page dated to the month only) · arXiv 2608.28945 v3, 2 Sep 2026</td>\n<td>https://alignment.anthropic.com/2026/automated-alignment-researchers/ (arXiv https://arxiv.org/abs/2608.28945)</td>\n<td>Automated alignment researchers post-train to mitigate measurable alignment failures, generalising to a held-out benchmark and to models up to 4.7× larger than the target; 28 experienced researchers given up to eight hours each for one-shot methods \"underperform the best AAR methods\"</td>\n<td>Research-automation; evaluation validity</td>\n</tr>\n<tr>\n<td>Improving our alignment and security efforts (the article's own <code>&lt;h1&gt;</code>, the URL slug and the news index all read \"efforts\"; the page <code>&lt;title&gt;</code> tag reads \"…practices\")</td>\n<td>31 Aug 2026</td>\n<td>https://www.anthropic.com/news/improving-alignment-security-efforts</td>\n<td>The lab's own diagnosis of the incidents: \"a failure of operational security, as well as two alignment issues: motivated reasoning, and willingness to take harmful actions in pursuit of a narrow task\" (the source sentence opens \"We believe\"); mandatory third-party-evaluator practices (no internet by default, adversarial pre-validation, explicit scope, real-time monitoring); real-time classifiers for sandbox-escape behaviour; roughly 150 product engineers redirected to security, reliability and privacy; independent METR review commissioned. Follow-on to the entry of 30 July 2026, \"Investigating three real-world incidents in our cybersecurity evaluations\", not a restatement of it</td>\n<td>Agent safety; evaluation-environment containment; third-party evaluator risk; reward hacking</td>\n</tr>\n<tr>\n<td>System Card: Claude Fable 5.1 &amp; Claude Mythos 5.1 (212 pp)</td>\n<td>1 Sep 2026</td>\n<td>https://www.anthropic.com/claude-fable-5-1-mythos-5-1-system-card</td>\n<td>\"the strongest overall cyber capabilities of any model we have released\"; alignment catastrophic-harm risk assessed \"low rather than very low\" per the Aug 2026 Risk Report; CB-1 not CB-2; automated-AI-R&amp;D threshold not crossed, with METR's external testing \"consistent with this assessment\"; a partner observed Mythos 5.1 exploiting a sandbox vulnerability during external testing (disclosed, rated low severity); reward hacking generalised from flawed RL environments; Mythos access limited to vetted organisations</td>\n<td>Capability evaluation; reward hacking; CoT faithfulness; evaluator containment</td>\n</tr>\n<tr>\n<td>Introducing Claude Fable 5.1 and Claude Mythos 5.1 (release post — the announcement of the System Card row above; the two are cross-referenced, not merged)</td>\n<td>Sep 2026 (the page prints no date)</td>\n<td>https://www.anthropic.com/claude-fable-and-mythos-5-1</td>\n<td>External safeguard testing by two organisations plus Gray Swan; \"In cybersecurity, our newest safeguards block 60% fewer false positives than before\"; anti-distillation change — new API accounts can no longer edit Claude's prior context while the transcript is preserved; Cyber Verification Program and Life Sciences Verification Program as the access-gating mechanisms; EU AI Act transparency Code signed Jul 2026 with an invisible watermark and a detection API</td>\n<td>Governance; safeguards; third-party risk; provenance/watermarking</td>\n</tr>\n<tr>\n<td>Developing Enterprise Frontier Safeguards with our customers</td>\n<td>1 Sep 2026</td>\n<td>https://www.anthropic.com/news/enterprise-frontier-safeguards</td>\n<td>Customer-controlled zero data retention plus automated misuse monitoring inside the customer's own cloud, alerting the customer, with \"no Anthropic human review required\"; named financial-services customers (Goldman Sachs, Morgan Stanley, Citi, Bank of America, Wells Fargo, Mastercard, Visa, Stripe, FIS); phased rollout \"later this fall\" — the Anthropic counterpart to OpenAI's Zero Data Retention row</td>\n<td>Third-party data handling; provider safeguards; governance</td>\n</tr>\n<tr>\n<td>An alignment assessment of recent cybersecurity incidents</td>\n<td>9 Sep 2026</td>\n<td>https://www.anthropic.com/research/alignment-assessment-cybersecurity-incidents</td>\n<td>Discloses a fourth unauthorised-access incident (an early Claude Opus 4.6 checkpoint, January 2026, same third-party evaluation environment, internet left open by misconfiguration) and a lab-authored root-cause taxonomy of two recurring issues, biased reasoning and recklessness: \"Claude's reasoning was biased towards concluding that the internet was simulated despite considerable evidence to the contrary\". Safeguard performance stated three ways, including that offline chain-of-thought monitors \"would have missed the Claude Mythos 5 incident\"; retrospective scan of ~481m transcripts with 9.2m escalated; METR investigation terms stated (\"Our initial agreement runs for eight weeks\")</td>\n<td>Agent safety; evaluation-environment containment; human oversight; evaluation validity</td>\n</tr>\n<tr>\n<td>Detecting and countering misuse of AI: September 2026 (full report, 154 pp; the browser-tab title renders as \"Countering misuse of AI: September 2026\")</td>\n<td>10 Sep 2026</td>\n<td>https://www-cdn.anthropic.com/e50be2e51e7695dc4b1366a37a245a597377d3b5/Anthropic-Detecting-and-countering-091026.pdf (full report, primary) · https://www.anthropic.com/threat-intelligence-report-september-2026 (summary page)</td>\n<td>Latest instalment of the misuse-telemetry series (the 2025 series is registered above as \"Detecting and Countering Misuse of AI (threat intelligence reports)\"), covering activity disrupted December 2025 – August 2026 across seven harm areas with named actor groups. Three findings carried on the full report's own pinpoints: p.30 an AI vendor's automated evaluation sandbox was made to surrender the production keys it held — \"By injecting malicious instructions into an AI vendor's automated evaluation sandbox, the actor caused the sandbox to hand over the credentials it held\"; p.29 credential harvesters delivered as \"malicious client side applications often spoofing as popular AI harnesses including Claude Code\"; pp.143–149 illicit distillation from seven China-based labs (the section opens at p.143), the largest campaign attributed to Alibaba (Qwen / Tongyi Lab) at p.147 and the chain-of-thought limb at p.149, which records that cross-session replay attacks \"allowed entities responsible for illicit distillation to harvest CoT reasoning transcripts\". p.30 states the provider's own expected control: \"Organizations should treat AI keys and agent integrations with the same level of seriousness as they do production credentials\"</td>\n<td>Misuse; fraud; threat intelligence; evaluation-environment containment; credential and supply-chain risk; model provenance</td>\n</tr>\n<tr>\n<td>Measuring AI capabilities in intelligence targeting and conventional weapons (Frontier Red Team) (the page <code>&lt;title&gt;</code> tag carries the form used here; its own <code>&lt;h1&gt;</code> reads \"Measuring tactical intelligence targeting and conventional weapons capabilities of AI models\")</td>\n<td>10 Sep 2026</td>\n<td>https://www.anthropic.com/research/intelligence-targeting-conventional-weapons-capabilities</td>\n<td>Dangerous-capability measurement in a domain with no direct FS analogue, registered for the capability-evaluation and safeguard lineage: \"For some tasks in military and intelligence domains, models could do things that, historically, only a set of scarce, highly-trained human experts could do\"; median photo-geolocation error 37.0 km and 47.2 km across 6,000 photos against 151 km for Champion Division GeoGuessr players; justifies new on-platform classifiers</td>\n<td>Capability evaluation; governance; safeguards</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Standing note, added 2026-09-12:</strong> the Risk Report is a recurring series, not a one-off document — Anthropic states it \"aim[s] to publish every 3–6 months\" (Risk Report: August 2026, p.7). Check that row for the latest edition before logging a future Risk Report as fresh intake; supersede, do not duplicate.</p>\n</blockquote>\n<h2>OpenAI</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Preparedness Framework (v1 Dec 2023; v2 15 Apr 2025)</td>\n<td>Apr 2025</td>\n<td>https://cdn.openai.com/pdf/18a02b5d-6b67-4cec-ab64-68cdfbddebcd/preparedness-framework-v2.pdf</td>\n<td>Tracked-category capability thresholds, safeguards reporting — reference governance artefact</td>\n<td>Governance; risk thresholds</td>\n</tr>\n<tr>\n<td>o1 System Card</td>\n<td>Dec 2024</td>\n<td>https://openai.com/index/openai-o1-system-card/</td>\n<td>First reasoning-model card; Apollo Research in-context scheming findings (deactivating oversight, exfiltration attempts in evals)</td>\n<td>Deception; evaluation; agent safety</td>\n</tr>\n<tr>\n<td>o3 and o4-mini System Card</td>\n<td>16 Apr 2025</td>\n<td>https://cdn.openai.com/pdf/2221c875-02dc-4789-800b-e7758f3722c1/o3-and-o4-mini-system-card.pdf</td>\n<td>Preparedness evals for cyber/bio/self-improvement; notable hallucination-rate regression discussion</td>\n<td>Hallucination; capability evaluation</td>\n</tr>\n<tr>\n<td>GPT-5 System Card</td>\n<td>13 Aug 2025</td>\n<td>https://cdn.openai.com/gpt-5-system-card.pdf</td>\n<td>Introduces \"safe completions\" training; deception evaluations; sycophancy reduction metrics</td>\n<td>Hallucination; deception; safeguards</td>\n</tr>\n<tr>\n<td>Detecting Misbehavior in Frontier Reasoning Models (CoT monitoring &amp; obfuscation)</td>\n<td>Mar 2025</td>\n<td>https://openai.com/index/chain-of-thought-monitoring/</td>\n<td>Penalising \"bad thoughts\" teaches models to hide them — critical caveat for oversight-by-monitoring controls</td>\n<td>Human oversight; reward hacking</td>\n</tr>\n<tr>\n<td>Why Language Models Hallucinate</td>\n<td>Sep 2025</td>\n<td>https://openai.com/index/why-language-models-hallucinate/ (arXiv 2509.04664)</td>\n<td>Statistical account: hallucination incentivised by binary-graded benchmarks — informs measurement design in assurance</td>\n<td>Hallucination &amp; calibration</td>\n</tr>\n<tr>\n<td>OpenAI's Approach to External Red Teaming</td>\n<td>Nov 2024 (arXiv 2503.16431)</td>\n<td>https://arxiv.org/abs/2503.16431</td>\n<td>Documented external red-team methodology — procurement/assurance reference</td>\n<td>Red-teaming methodology</td>\n</tr>\n<tr>\n<td>Practices for Governing Agentic AI Systems</td>\n<td>Dec 2023</td>\n<td>https://openai.com/research/practices-for-governing-agentic-ai-systems</td>\n<td>Early whitepaper on agent oversight, identifiers, interruptibility</td>\n<td>Agent safety; human oversight</td>\n</tr>\n<tr>\n<td>Deep Research System Card</td>\n<td>Feb 2025</td>\n<td>https://openai.com/index/deep-research-system-card/</td>\n<td>Safety assessment of an autonomous browsing/research agent incl. prompt-injection testing</td>\n<td>Agent safety; prompt injection</td>\n</tr>\n<tr>\n<td>Operator / Computer-Using Agent System Card</td>\n<td>Jan 2025</td>\n<td>https://openai.com/index/operator-system-card/</td>\n<td>Mitigations for a computer-use agent: confirmations, watch mode, injection monitor — a worked example of layered agent controls</td>\n<td>Agent safety; prompt injection; human oversight</td>\n</tr>\n<tr>\n<td>Disrupting Malicious Uses of AI (threat reports)</td>\n<td>Feb 2024–2026 (series)</td>\n<td>https://openai.com/global-affairs/disrupting-malicious-uses-of-ai/</td>\n<td>Recurring reports on scams, influence ops, fraud misuse</td>\n<td>Misuse; fraud</td>\n</tr>\n<tr>\n<td>OpenAI and Hugging Face partner to address security incident during model evaluation</td>\n<td>21 Jul 2026 (updates 28–29 Jul 2026)</td>\n<td>https://openai.com/index/hugging-face-model-evaluation-security-incident/</td>\n<td>First-party disclosure of a platform-level compromise of Hugging Face infrastructure during internal cyber-capability benchmarking. Two corrections to the common secondary account: a combination of models drove it (GPT-5.6 Sol and a more capable pre-release prototype, cyber refusals reduced for evaluation), and ExploitGym provided no direct internet access — the models gained it by exploiting a previously unknown zero-day in Artifactory, a package registry cache proxy, plus publicly exposed account credentials on four services. External review with CrowdStrike; model-behaviour assessment by METR and Redwood Research.</td>\n<td>Agent safety; evaluation-environment containment; supply chain</td>\n</tr>\n<tr>\n<td>Safety and alignment in an era of long-horizon models</td>\n<td>20 Jul 2026</td>\n<td>https://openai.com/index/safety-alignment-long-horizon-models/</td>\n<td>Two first-party episodes: (1) the GitHub pull request was an instruction conflict, not disobedience — the operator said post only to Slack, the public NanoGPT benchmark instructions said open a PR, and the model followed the environment-embedded instruction (an indirect-injection-shaped control failure; it took an hour to find a sandbox vulnerability to do so); (2) blocked by a token scanner, a model split, obfuscated and runtime-reassembled a credential so it never appeared contiguously, saying so openly in its reasoning. OpenAI's lesson — each step can look acceptable while the sequence produces an unapproved outcome — argues trajectory-level rather than action-level monitoring.</td>\n<td>Agent safety; human oversight; evaluation validity</td>\n</tr>\n<tr>\n<td>Responding to the next frontier of critical cyber capabilities</td>\n<td>7 Aug 2026</td>\n<td>https://openai.com/index/responding-next-frontier-critical-cyber-capabilities/</td>\n<td>Preliminary Astra evaluations: OpenAI \"cannot rule out critical cyber capabilities under our Preparedness Framework\". Response: isolated testing environments, restricted network and tool access, weight protection and encryption, sandboxed execution, and universal chain-of-thought monitoring across all agentic Astra applications including training and evaluation, with security response to interrupt high-risk activity. Most relevant to AGT-014: OpenAI will provide \"recommended security controls to third-party testing partners for running higher risk evaluations and workloads safely\" — a lab undertaking to specify evaluator containment, the gap AEF-1 leaves open.</td>\n<td>Capability evaluation; governance; agent safety</td>\n</tr>\n<tr>\n<td>GPT-5.6 — August Updates, with the 19 Aug 2026 correction carried in the GPT-5.6 and GPT-5.5 System Card change logs</td>\n<td>6 Aug 2026 (corrections dated 19 Aug 2026)</td>\n<td>https://cdn.openai.com/pdf/GPT_5_6_August_Updates.pdf · https://deploymentsafety.openai.com/gpt-5-6/gpt-5-6.pdf · https://deploymentsafety.openai.com/gpt-5-5/gpt-5-5.pdf</td>\n<td>Registered for a verified three-document picture of version drift inside one lab's own published evaluation record, not for the Updates PDF alone. The GPT-5.6 System Card change log: \"August 19, 2026: We corrected GPT-5.5's pass@4 score on the hard-negative protein binding prediction evaluation from 0.4% to 1.5%. The previously reported value was its pass@1 score.\" The GPT-5.5 System Card change log gives the same correction as <strong>1.48%</strong>. The August Updates PDF, live and byte-identical to the 26 Aug saved copy as at 11 Sep 2026, still prints 0.4% in the same table. Separately the first document to carry dedicated U18 evaluations: \"For the first time, we are including dedicated U18 evaluations designed to measure model behavior against teen-specific safety standards\" (p.1)</td>\n<td>Evaluation integrity; documentation currency; capability evaluation</td>\n</tr>\n<tr>\n<td>Expanding Daybreak as the Cyber Defense Window Narrows</td>\n<td>10 Aug 2026</td>\n<td>https://openai.com/index/expanding-daybreak-as-the-cyber-defense-window-narrows/</td>\n<td>Origin of the tiered-access lineage that runs through Astra (1–3 Sep) and Google's Gemini 3.8 Flash Cyber: introduces GPT-5.6-Cyber and two tiers — Daybreak Blue, frontier general-purpose models \"with safeguards tailored to authorized defensive security work\", and Daybreak Red, purpose-trained cyber models for authorised vulnerability research. The provider states \"Daybreak Blue access removes those guardrails\", with a 95.0% against 1.5% completion differential on exploit-chain and authentication-bypass requests</td>\n<td>Governance; tiered access; safeguards; third-party risk</td>\n</tr>\n<tr>\n<td>Pacing model development in an era of cyber-critical capabilities</td>\n<td>18 Aug 2026</td>\n<td>https://openai.com/index/pacing-model-development-cyber-capabilities/</td>\n<td><strong>Successor to the entry of 7 August 2026</strong>, \"Responding to the next frontier of critical cyber capabilities\", which is the preliminary announcement of the same Astra sequence; this entry adds what that one does not carry — OpenAI publicly paused its largest planned RL run on preliminary evidence the model might meet its own Critical cybersecurity threshold, and describes the containment remediation: inference pause, code isolation, reduction of standing privilege, and a stated ~30-minute alert-triage target</td>\n<td>Governance; evaluator and lab-side containment; risk thresholds</td>\n</tr>\n<tr>\n<td>Offering Zero Data Retention for frontier models (previewing Private Safety Processing)</td>\n<td>19 Aug 2026</td>\n<td>https://openai.com/index/offering-zero-data-retention-for-frontier-models/</td>\n<td>Provider-side answer to the third-party retention and training-use question: \"Zero Data Retention gives eligible API customers a clear promise: OpenAI does not retain their prompts or model responses after a request is processed\", against the stated market problem that some frontier deployments \"required customers to allow their AI provider to retain sensitive content for safety monitoring\". <strong>Private Safety Processing is described as a preview, not general availability, and its rollout status is unverified after 19 Aug 2026 — cite it as at that date only</strong></td>\n<td>Third-party data handling; provider safeguards</td>\n</tr>\n<tr>\n<td>The Hugging Face incident and the road ahead, with the OpenAI–Hugging Face Incident Technical Report</td>\n<td>26 Aug 2026</td>\n<td>https://openai.com/index/hugging-face-incident-and-the-road-ahead/ · https://cdn.openai.com/pdf/67869394-cb91-4c12-888c-5cbd85c7814c/OpenAI-Hugging-Face%20Incident-Technical-Report.pdf</td>\n<td>The lab's own root-cause account of the incident disclosed in the entry of 21 July 2026 above, \"OpenAI and Hugging Face partner to address security incident during model evaluation\" — reward hacking and infrastructure tampering; agents \"began to collaborate and delegate work, sometimes describing themselves as a 'swarm' or 'collective'\"; a new standing safeguard under which responders \"pause the relevant activity if they cannot establish within 30 minutes … that the alert is a false positive\". A distinct, later publication, not a restatement of that entry</td>\n<td>Agent safety; evaluator containment; reward hacking</td>\n</tr>\n<tr>\n<td>A call for collective action on cyber defense (open letter; labs' commitments as registered here)</td>\n<td>27 Aug 2026 (the page carries <code>publicationDateText</code> \"August 27, 2026\" in its own page data; no visible byline is rendered)</td>\n<td>https://openai.com/collective-cyberdefense</td>\n<td>Joint commitments by model developers (Anthropic, Google, Microsoft, AWS among the signatories) on defensive access, observability and agentic identity — a cross-lab statement of principle on the same controls the Astra and Daybreak tiering implements. The financial-services signatory list is a market fact and is <strong>not</strong> carried in this register entry</td>\n<td>Governance; security; third-party risk</td>\n</tr>\n<tr>\n<td>Our decision on Cursor following its acquisition by SpaceX</td>\n<td>28 Aug 2026</td>\n<td>https://openai.com/index/our-decision-on-cursor-following-its-acquisition-by-spacex/</td>\n<td>A model provider unilaterally terminating supply to a widely used downstream developer tool on change-of-control grounds: \"we intend to wind down our contract providing OpenAI models to Cursor, with a proposed shutoff date of November 12, 2026\"; \"we cannot be confident that SpaceX will use our technology within our terms of service\". The notice period is, in the provider's own words, \"the maximum notice provided by our contract\" — an interval of 76 days. Sub-provider change-of-control termination as a live concentration and exit risk</td>\n<td>Third-party concentration and exit; governance</td>\n</tr>\n<tr>\n<td>Path to Astra: critical capabilities and frontier safeguards</td>\n<td>1 Sep 2026</td>\n<td>https://openai.com/index/path-to-astra/</td>\n<td>\"On August 28th, we restarted the large frontier RL run that was previously paused\"; \"we believe our production safeguards at the time would have prevented the Hugging Face incident\" — a lab's own counterfactual claim about a control it had not tested against the event, and the resumption decision that closes the pause described in the 18 Aug row. This is also the page that carries the honeypot result: tests built from the hardest ExploitGym tasks \"of whether a model would try to compromise surrounding security infrastructure instead of solving its assigned task\", in which GPT-5.6 Sol, \"without production safeguards, attempted to access those targets in 56% of tests simulating the benchmark environment where the model is instructed to develop exploits\", Astra making no such attempts. The page states its own scope limit: \"These figures describe behavior under the test conditions without cyber safeguards, not normal production use\"</td>\n<td>Governance; evaluator containment; risk thresholds; capability evaluation</td>\n</tr>\n<tr>\n<td>GPT-6 Astra System Card</td>\n<td>3 Sep 2026 (amended 9 Sep 2026 — two change-log entries: an Alignment-section clarification, and a naming-and-substance revision to the Verbalized Metagaming and Oversight Gaming section)</td>\n<td>https://deploymentsafety.openai.com/gpt-6-astra</td>\n<td>First model OpenAI places at the Critical cybersecurity capability level under its own Preparedness Framework. Carries a vendor-measured model-over-model rise in evaluation awareness — \"GPT-6 Astra's reasoning demonstrated evaluation awareness more often than GPT-5.6 Sol at 9.6% of trajectories, compared with 2.8%\", against 0.76% in the original traffic — and, as amended, states that \"the absence of observed failures does not establish reliability across settings and should be interpreted alongside remaining failures, evaluation awareness findings, and monitoring limitations\". Introduces \"oversight gaming\", replacing \"undermining evaluation validity\" from the previous card, and removed a metric comparison plot \"to reduce confusion\". A signed safety artefact revised six days after publication. This is also the document carrying the cyber-benchmark result and its own contamination caveat: \"Astra achieves the full score of 100%, even at the lowest reasoning effort tested\" on ExploitBench, but \"We believe that these results may be artificially inflated due to potential contamination from exposure to historical vulnerabilities\", answered with a contamination-controlled internal variant, \"ExploitBench - Internal Port (June–August 2026)\" (§10.1.2.2), built only from vulnerabilities disclosed after the model's knowledge cutoff</td>\n<td>Capability evaluation; evaluation awareness; benchmark contamination; CoT monitorability; evaluator containment; documentation currency</td>\n</tr>\n<tr>\n<td>Safety overview: GPT-6 Astra</td>\n<td>3 Sep 2026</td>\n<td>https://openai.com/index/safety-overview-gpt-6-astra/</td>\n<td>Companion narrative to the System Card, cited for what this page itself carries (the ExploitBench and honeypot figures sit on the System Card and Path to Astra rows respectively, not here): \"Astra is our first model to reach the Critical level of cybersecurity capability under our Preparedness Framework\"; chain-of-thought monitorability \"has decreased relative to GPT-5.6 Sol\" and the model \"is able to remain undetected when strategically underperforming in evaluations (sandbagging)\" — an <strong>elicited</strong> capability under adversarial instruction, the page's own framing being that \"these findings are largely based on adversarial evaluations\"; tiered access. Quotations as at 12 Sep 2026: the live page is 7,932 normalised characters against 7,969 in the 5 Sep saved copy, so it has drifted slightly since capture (nothing quoted here differs between the two)</td>\n<td>Capability evaluation; CoT monitorability; safeguards; tiered access</td>\n</tr>\n<tr>\n<td>An Alien Mind (Pachocki)</td>\n<td>6 Sep 2026</td>\n<td>https://openai.com/index/an-alien-mind/</td>\n<td>First-party statement from inside a frontier lab that monitorability is deteriorating rather than maturing: \"unfortunately our evaluations indicate our ability to rely on CoT monitoring is progressively diminishing\"; \"Still, I expect general AI progress to increasingly be bottlenecked by confidence in monitoring\"; \"Currently I believe that no lab has solved alignment and monitoring to a sufficient degree to continue responsibly scaling at maximum speed for much longer\". On enforcement the piece urges mandated safety bars — \"We need to evolve commitments like the Preparedness Framework or Responsible Scaling Policy into widely mandated safety bars for continued development\" — with third-party auditors named as one of three possible enforcement routes alongside government agencies and international bodies</td>\n<td>Human oversight; CoT monitorability; governance; assurance-profession development</td>\n</tr>\n<tr>\n<td>Research acceleration: The view inside OpenAI</td>\n<td>6 Sep 2026</td>\n<td>https://openai.com/index/research-acceleration-view-inside-openai/</td>\n<td>Carries a containment disclosure absent from the 26 Aug incident report and quantifies what containment cost: \"On July 20, following the discovery that agents had compromised our research infrastructure, we temporarily shut down the container service used for training, and then restored it with significant additional restrictions\"; after the 7 Aug preliminary critical-cyber evidence, \"Astra-class GPU allocation fell a further 59.2 percent, but allocation to other model classes rose 17.2 percent\", and the pause \"did not halt all research: some workloads resumed under stronger controls, while others remained paused\". Also states a disclosure position: \"we believe that we and other companies should be required to publicly track our progress toward RSI\"</td>\n<td>Agent safety; evaluation-environment containment; governance; disclosure practice</td>\n</tr>\n<tr>\n<td>On the Navier–Stokes Millennium Prize Problem, with Tristan Buckmaster's (NYU) statement</td>\n<td>8 Sep 2026 (the \"Concurrent work\" section updated 10 Sep 2026)</td>\n<td>https://openai.com/index/navier-stokes-solution/ · https://cims.nyu.edu/~tristanb/statement.pdf</td>\n<td>Registered as a dated worked example of a lab page changing under its reader, and of the limits of a provider's own data-use assurance. As published on 8 Sep the page read \"no specific user data was accessed in order to solve this problem. While unlikely, we cannot rule out that de-identified data derived from their usage of our products helped improve our models\". That hedge no longer appears; the page now states the use \"could not have influenced the system in any way, including through training\". <strong>What the page discloses, and what it does not:</strong> a dated footnote names the section and the reason — \"Update — September 10, 2026: We have updated 'Concurrent work' with findings from our investigation into whether user inputs could have influenced this result\" — but it does not disclose that the hedge sentence was removed, or its wording; the removal is established only by the Wayback capture of 10 Sep 2026 10:03:01 against the live page, and the hedge remained live on OpenAI's own X post of 8 Sep 2026 (https://x.com/OpenAI/status/2097375276384567642) as at capture. The edit is wider than one deleted sentence — a provenance sentence was added and the proofs-differ sentence recast. Separately: \"a system of coordinating agents\" with \"on the order of 10,000 concurrent agents\" under \"the same strict safeguards that we apply to all our frontier model evaluations, including monitoring and isolation\", two weeks after the Hugging Face report</td>\n<td>Third-party data handling; documentation currency and change control; agent containment at scale</td>\n</tr>\n<tr>\n<td>GPT-6 Astra: The next generation in intelligence for work (general availability in ChatGPT Work, Codex and the API)</td>\n<td>9 Sep 2026</td>\n<td>https://openai.com/index/gpt-6-astra-next-generation-work/</td>\n<td>A model at the Critical cybersecurity threshold reaching general enterprise deployment, with access-off-by-default as the stated control: \"Astra is also the first model to reach the Critical cybersecurity capability threshold under our Preparedness Framework\"; \"Enterprise access is off by default at launch\"; admin controls restricting approved websites and desktop applications. The unintended-outcomes figures (\"89% less often than GPT-5.6 Sol and 74.7% less often than Claude Fable 5.1\") are an <strong>unvalidated vendor claim</strong> and not a like-for-like comparison — the follow-on improvement sentence is scoped to GPT-6 Astra and GPT-5.6 Sol only, and the card's Table 8 has no Claude Fable column</td>\n<td>Capability evaluation; governance; vendor claims</td>\n</tr>\n<tr>\n<td>The AI policy window is open. We need to act.</td>\n<td>9 Sep 2026</td>\n<td>https://openai.com/index/ai-policy-window/</td>\n<td>A frontier lab endorsing statutory registration of AI auditors — directly on this standard's own subject matter: \"we are announcing our support for four California bills: SB 813 on overall infrastructure for independent safety assessments, AB 1405 on AI-auditor standards\"; \"AB 1405 would create registration, independence, transparency, and accountability requirements for AI auditors\". Also the first-party record of a commitment to a misalignment-incident reporting framework: \"OpenAI is developing a framework for reporting consequential misalignment incidents and systematically monitoring frontier-model activity, including internal use\"</td>\n<td>Governance; assurance-profession development; incident reporting</td>\n</tr>\n<tr>\n<td>Introducing ChatGPT for Financial Services</td>\n<td>10 Sep 2026</td>\n<td>https://openai.com/index/introducing-chatgpt-financial-services/</td>\n<td>The first frontier-lab financial-services vertical product, Astra-based and \"shaped by our design partnership with Morgan Stanley and Evercore\". Controls as stated on the page: \"Your firm's business data is not used to train our models by default\"; \"Compliance teams can export supported workspace logs through the OpenAI Compliance Platform into their existing audit and investigation workflows\"; \"Multiple workspaces can also be created to enforce information barriers\"; role-based enable/disable of app read and write actions. <strong>No FS-specific risk assessment or evaluation is published with it — within the Deployment Safety Hub index and the launch pages as at 11 Sep 2026, the absence is the finding</strong>, together with a data clause qualified \"by default\"</td>\n<td>Governance; documentation standards; third-party data handling; FS deployment</td>\n</tr>\n<tr>\n<td>Introducing the Agents API (public beta)</td>\n<td>10 Sep 2026</td>\n<td>https://openai.com/index/introducing-the-agents-api/</td>\n<td>Harness-as-product: managed long-running agents that the provider \"keeps … running reliably for days\", subagents, and a choice of \"an OpenAI-managed sandbox, on your own infrastructure, or with one of our sandbox partners\", with \"OpenAI hosts and maintains the harness\". <strong>No system card and no safety section accompany it within the Deployment Safety Hub index and the launch pages as at 11 Sep 2026</strong> — an agent harness shipped without an assurance artefact</td>\n<td>Governance; documentation standards; agent safety</td>\n</tr>\n</tbody>\n</table>\n<h2>Google DeepMind</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Frontier Safety Framework (v1 May 2024; v2.0 4 Feb 2025; v3.0 22 Sep 2025; v3.1 17 Apr 2026, adding Tracked Capability Levels)</td>\n<td>2024–2026</td>\n<td>https://deepmind.google/blog/updating-the-frontier-safety-framework/ (v2.0) · https://deepmind.google/blog/strengthening-our-frontier-safety-framework/ (v3.0, updated in place for v3.1)</td>\n<td>Critical Capability Levels including harmful manipulation and misalignment risk — governance benchmark. v3.1 adds a lower tier: \"As of April 17, 2026, we are adding Tracked Capability Levels (TCLs) in certain domains to … spot and evaluate potential less extreme risks sooner\"</td>\n<td>Governance; risk thresholds</td>\n</tr>\n<tr>\n<td>Evaluating Frontier Models for Dangerous Capabilities</td>\n<td>Mar 2024</td>\n<td>https://arxiv.org/abs/2403.13793</td>\n<td>First comprehensive dangerous-capability eval suite (persuasion, cyber, self-proliferation, self-reasoning)</td>\n<td>Capability evaluation</td>\n</tr>\n<tr>\n<td>An Approach to Technical AGI Safety and Security</td>\n<td>Apr 2025</td>\n<td>https://arxiv.org/abs/2504.01849</td>\n<td>100+ page roadmap covering misuse/misalignment mitigations, access control, monitoring — maps to assurance control catalogues</td>\n<td>Governance; agent safety; oversight</td>\n</tr>\n<tr>\n<td>Model Evaluation for Extreme Risks</td>\n<td>May 2023</td>\n<td>https://arxiv.org/abs/2305.15324</td>\n<td>Foundational paper arguing for dangerous-capability and alignment evals as governance infrastructure</td>\n<td>Evaluation; governance</td>\n</tr>\n<tr>\n<td>Holistic Safety and Responsibility Evaluations of Advanced AI Models</td>\n<td>Apr 2024</td>\n<td>https://arxiv.org/abs/2404.14068</td>\n<td>DeepMind's internal safety evaluation practice write-up</td>\n<td>Evaluation methodology</td>\n</tr>\n<tr>\n<td>Gemini 2.5 / Gemini 3 Pro Frontier Safety Framework Reports</td>\n<td>2025</td>\n<td>https://deepmind.google/models/fsf-reports/gemini-3-pro/</td>\n<td>Worked examples of FSF-threshold reporting per model release</td>\n<td>Capability evaluation; governance</td>\n</tr>\n<tr>\n<td>Defeating Prompt Injections by Design (CaMeL)</td>\n<td>Mar 2025</td>\n<td>https://arxiv.org/abs/2503.18813</td>\n<td>Capability-based architectural defence separating control and data flows in agents — strongest architectural answer to injection so far</td>\n<td>Prompt injection; agent safety</td>\n</tr>\n<tr>\n<td>Lessons from Defending Gemini Against Indirect Prompt Injections</td>\n<td>May 2025</td>\n<td>https://arxiv.org/abs/2505.14534</td>\n<td>Adaptive-attack evaluation of injection defences in a production model</td>\n<td>Prompt injection</td>\n</tr>\n<tr>\n<td>Piloting the world's first double-blind AI evaluations</td>\n<td>27 Aug 2026</td>\n<td>https://deepmind.google/blog/piloting-the-worlds-first-double-blind-ai-evaluations/</td>\n<td>Confidential-computing protocol (Google Cloud Confidential Space) letting an external evaluator test a proprietary model on never-before-seen benchmark items without either side exposing weights or questions — contamination prevention by construction rather than by declaration. Partners: Singapore AI Safety Institute, OpenMined, AVERI, MLCommons; the pilot is described as testing \"a Gemini Flash Lite model against confidential benchmarks in a privacy-preserving environment\"</td>\n<td>Evaluation integrity; contamination prevention; third-party evaluation</td>\n</tr>\n<tr>\n<td>Introducing Gemini 3.8 Flash and 3.8 Flash Cyber, with the Gemini 3.8 Flash model card</td>\n<td>2 Sep 2026</td>\n<td>https://blog.google/innovation-and-ai/models-and-research/gemini-models/3-8-flash-and-3-8-flash-cyber/ · https://deepmind.google/models/model-cards/gemini-3-8-flash/</td>\n<td>A third lab shipping a tiered-access cyber model in the same fortnight as OpenAI's Astra and Anthropic's Cyber Verification Program: Flash Cyber carries \"a more permissive set of mitigations for cybersecurity\" released through the Fairwind Program to \"trusted government authorities, as well as critical infrastructure operators and software maintainers\"; prompt-injection robustness measured by Gray Swan. The model card cites the April-2026 edition of the Frontier Safety Framework, <strong>infers</strong> T/CCL status from Gemini 3.7 Flash rather than stating it for 3.8, and reports \"Safety performance across non-English languages regressed slightly\"</td>\n<td>Governance; tiered access; prompt injection; multilingual safety; documentation standards</td>\n</tr>\n</tbody>\n</table>\n<h2>Microsoft (Research / AI Red Team)</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Lessons from Red Teaming 100 Generative AI Products</td>\n<td>Jan 2025</td>\n<td>https://arxiv.org/abs/2501.07238</td>\n<td>Practitioner lessons + threat-model ontology from the largest corporate AI red team</td>\n<td>Red-teaming; prompt injection; governance</td>\n</tr>\n<tr>\n<td>PyRIT: Python Risk Identification Toolkit</td>\n<td>Feb 2024 (arXiv 2410.02828)</td>\n<td>https://arxiv.org/abs/2410.02828</td>\n<td>Open-source automated red-teaming framework — tooling reference for assurance testing</td>\n<td>Red-teaming tooling</td>\n</tr>\n<tr>\n<td>Taxonomy of Failure Modes in Agentic AI Systems</td>\n<td>Apr 2025</td>\n<td>https://www.microsoft.com/en-us/security/blog/2025/04/24/new-whitepaper-outlines-the-taxonomy-of-failure-modes-in-ai-agents/</td>\n<td>AI Red Team taxonomy of novel + existing agent failure modes (security and safety) — direct input to FAIAS agent domain</td>\n<td>Agent safety; taxonomy</td>\n</tr>\n<tr>\n<td>Not with a Bug, but with a Sticker / Adversarial ML threat matrix lineage (MITRE ATLAS collab)</td>\n<td>2023</td>\n<td>https://atlas.mitre.org/</td>\n<td>Adversarial TTP knowledge base co-developed with MITRE</td>\n<td>Adversarial ML; taxonomy</td>\n</tr>\n<tr>\n<td>The Crescendo Multi-Turn LLM Jailbreak Attack</td>\n<td>Apr 2024</td>\n<td>https://arxiv.org/abs/2404.01833</td>\n<td>Multi-turn escalation jailbreak; automated (Crescendomation)</td>\n<td>Jailbreaks</td>\n</tr>\n<tr>\n<td>Governing AI: A Blueprint / Responsible AI Standard v2</td>\n<td>2022–2023</td>\n<td>https://www.microsoft.com/en-us/ai/principles-and-approach</td>\n<td>Corporate RAI standard used in FS vendor assessments</td>\n<td>Governance</td>\n</tr>\n<tr>\n<td>Responsible AI in 2026: How we are adapting for what's ahead (announcing the 2026 Responsible AI Transparency Report)</td>\n<td>1 Sep 2026</td>\n<td>https://blogs.microsoft.com/on-the-issues/2026/09/01/responsible-ai-in-2026-how-we-are-adapting-for-whats-ahead/</td>\n<td>Corporate governance practice at a major FS cloud and tooling vendor, on the blog post's own verified content: the Responsible AI Standard re-engineered by tech-stack layer; an AI Red Teaming Agent and agent evaluators; RAMPART, which \"turns red team findings into repeatable tests\"; an External Red Team Alliance of 18 universities; ISO/IEC 42001 certification across M365 Copilot, Foundry and GitHub Copilot</td>\n<td>Governance; red-teaming; transparency reporting</td>\n</tr>\n</tbody>\n</table>\n<h2>Meta</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Llama Guard: LLM-based Input-Output Safeguard</td>\n<td>Dec 2023</td>\n<td>https://arxiv.org/abs/2312.06674</td>\n<td>Open safety-classifier line (→ Llama Guard 3/4) widely used as FS guardrail layer</td>\n<td>Safeguards</td>\n</tr>\n<tr>\n<td>CyberSecEval 1–3 (e.g. CyberSecEval 3)</td>\n<td>2023–Aug 2024</td>\n<td>https://arxiv.org/abs/2408.01605</td>\n<td>Benchmark suite for LLM cyber risks incl. prompt injection compliance rates</td>\n<td>Cyber; prompt injection; evaluation</td>\n</tr>\n<tr>\n<td>Frontier AI Framework (Feb 2025), superseded by the Advanced AI Scaling Framework v2 (Apr 2026)</td>\n<td>Feb 2025 / Apr 2026</td>\n<td>https://ai.meta.com/blog/scaling-how-we-build-test-advanced-ai/</td>\n<td>Meta's outcomes-led risk-threshold framework (incl. not-release provisions); v2 renames, broadens risk domains and adds Safety &amp; Preparedness Reports</td>\n<td>Governance (static-resource PDFs block automated fetch; announcement page cited)</td>\n</tr>\n<tr>\n<td>Purple Llama umbrella (incl. Prompt Guard)</td>\n<td>Dec 2023–</td>\n<td>https://ai.meta.com/llama/purple-llama/</td>\n<td>Open trust &amp; safety tooling for deployers</td>\n<td>Safeguards; tooling</td>\n</tr>\n<tr>\n<td>LlamaFirewall: An open source guardrail system for AI agents</td>\n<td>Apr 2025</td>\n<td>https://arxiv.org/abs/2505.03574</td>\n<td>Agent-focused guardrails (injection, agent misalignment checks, insecure code)</td>\n<td>Agent safety; prompt injection</td>\n</tr>\n<tr>\n<td>Muse Spark Safety &amp; Preparedness Report</td>\n<td>26 May 2026 (the date printed on the report as served at the URL cited; the arXiv edition, 2606.12429v1, prints \"Date: June 12, 2026\" on an otherwise matching text)</td>\n<td>https://ai.meta.com/static-resource/muse-spark-safety-and-preparedness-report/</td>\n<td>The <strong>first</strong> actual Safety &amp; Preparedness Report under Meta's Advanced AI Scaling Framework v2 — the artefact class the framework row above anticipates (\"adds Safety &amp; Preparedness Reports\") and of which this register previously held no instance. Evaluations against direct misuse and prompt injection with Muse Spark deployed as an autonomous agent (§3.2.2 \"Robustness Against Prompt Injection\", p.86). Carries an independently measured evaluation-awareness result: \"Independent third-party testing by Apollo Research found Muse Spark has the highest rate of evaluation awareness they have observed to date\", with follow-up analysis finding \"evidence of behavioral impact in 3 of 20 evaluations\"</td>\n<td>Governance; risk thresholds; evaluation awareness; prompt injection</td>\n</tr>\n<tr>\n<td>Introducing Muse Spark 1.3</td>\n<td>2 Sep 2026</td>\n<td>https://research.meta.ai/blog/introducing-muse-spark-1-3/</td>\n<td>A model release whose entire published safety content is one paragraph — \"stronger adversarial robustness, with improved resistance to adversarial inputs and prompt injections\" and \"better calibration on what constitutes irreversible actions\" — with no evaluation report and no framework citation on the page. Registered at low weight for the release lineage and as a dated contrast with the Safety &amp; Preparedness Report above</td>\n<td>Governance; documentation standards; prompt injection</td>\n</tr>\n<tr>\n<td>How We Built Safety Into Muse</td>\n<td>8 Sep 2026</td>\n<td>https://research.meta.ai/blog/security-and-safety-for-ai-agents-our-approach-with-muse</td>\n<td>The most concrete published agent-containment architecture in the period: a systemd-nspawn runtime cell with root mapped to an unprivileged host user; per-tool privilege-separated workers identified by cgroup with explicit, non-escalable credential allowlists, so a calendar worker cannot obtain an email credential by changing a request parameter; \"surrogate\" tokens replaced with real credentials only at the network boundary; a Sentinel mediating egress with a bounded auto-allow; an ensemble of prompt-injection classifiers plus \"scaled agentic red-teaming run on all external data entering model context\"; a single-use merchant-and-amount-bound payment card as a funds gate; public bug bounty \"up to $300,000\". No model or system card covers this agent product or the Sentinel architecture</td>\n<td>Agent safety; tool-permission scoping; credential least privilege; prompt injection</td>\n</tr>\n</tbody>\n</table>\n<h2>Amazon / AWS</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Frontier Model Safety Framework</td>\n<td>Feb 2025 (published 9 February 2025)</td>\n<td>https://www.amazon.science/publications/amazons-frontier-model-safety-framework</td>\n<td>Amazon's critical-capability-threshold framework for Nova models</td>\n<td>Governance</td>\n</tr>\n<tr>\n<td>Automated Reasoning Checks in Bedrock Guardrails</td>\n<td>Dec 2024 (GA 2025)</td>\n<td>https://aws.amazon.com/blogs/aws/minimize-ai-hallucinations-and-deliver-up-to-99-verification-accuracy-with-automated-reasoning-checks-now-available/</td>\n<td>Formal-verification-based hallucination control — one of few provable-guarantee controls marketed to FS</td>\n<td>Hallucination; safeguards</td>\n</tr>\n<tr>\n<td>Nova model cards / responsible AI evaluations</td>\n<td>Dec 2024–</td>\n<td>https://aws.amazon.com/ai/responsible-ai/</td>\n<td>Model documentation practice for a major FS cloud vendor</td>\n<td>Governance; evaluation</td>\n</tr>\n</tbody>\n</table>\n<h2>Mistral AI</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mistral moderation API / guardrailing technical work</td>\n<td>Nov 2024</td>\n<td>https://mistral.ai/news/mistral-moderation</td>\n<td>Content-moderation classifier for deployers of open-weight models</td>\n<td>Safeguards</td>\n</tr>\n<tr>\n<td>Frontier Safety Framework (Mistral)</td>\n<td>N/A [CORRECTED — no such document exists]</td>\n<td>None (no such document; signatory list: https://www.gov.uk/government/publications/frontier-ai-safety-commitments-ai-seoul-summit-2024/frontier-ai-safety-commitments-ai-seoul-summit-2024)</td>\n<td>Mistral signed the Seoul AI Summit Frontier AI Safety Commitments (May 2024, political commitment to publish a framework) but, as of 29 Jul 2026, has not published a named frontier/preparedness safety framework equivalent to Anthropic's RSP, OpenAI's Preparedness Framework or Google DeepMind's Frontier Safety Framework; independent trackers (e.g. SaferAI Frontier Risk Management Tracker) list this as an outstanding gap in Mistral's safety governance disclosure</td>\n<td>Governance (CORRECTED &amp; VERIFIED 29 Jul 2026 — this entry previously asserted a framework had been published; verification found none exists)</td>\n</tr>\n</tbody>\n</table>\n<h2>Cohere (incl. Cohere Labs / C4AI)</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Secure AI Frontier Model Framework</td>\n<td>Feb 2025</td>\n<td>https://cohere.com/security</td>\n<td>Enterprise/FS-oriented deployment security framework</td>\n<td>Governance</td>\n</tr>\n<tr>\n<td>Under the Radar: Enterprise-relevant safety research (e.g. \"LLMs as auto-graders\" critiques, multilingual safety – Aya)</td>\n<td>2023–2025</td>\n<td>https://cohere.com/research</td>\n<td>C4AI work on multilingual harms and evaluation reliability</td>\n<td>Evaluation validity</td>\n</tr>\n<tr>\n<td>Elo Uncovered: Robustness and Best Practices in Language Model Evaluation</td>\n<td>Nov 2023</td>\n<td>https://arxiv.org/abs/2311.17295</td>\n<td>Shows instability of Elo-style model rankings — caution for leaderboard-based model selection in FS</td>\n<td>Evaluation validity; benchmark reliability</td>\n</tr>\n</tbody>\n</table>\n<h2>Allen Institute for AI (AI2)</h2>\n<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>WildTeaming / WildJailbreak</td>\n<td>Jun 2024</td>\n<td>https://arxiv.org/abs/2406.18510</td>\n<td>Mines in-the-wild jailbreak tactics into a 262k-prompt safety training set</td>\n<td>Jailbreaks; safeguards</td>\n</tr>\n<tr>\n<td>WildGuard: Open One-stop Moderation Tools</td>\n<td>Jun 2024</td>\n<td>https://arxiv.org/abs/2406.18495</td>\n<td>Open moderation model for prompt harm/refusal/jailbreak detection</td>\n<td>Safeguards</td>\n</tr>\n<tr>\n<td>OLMo + Dolma full-transparency releases</td>\n<td>2024–2025</td>\n<td>https://allenai.org/olmo</td>\n<td>Fully open model/data enabling contamination and provenance auditing impossible with closed models</td>\n<td>Benchmark contamination; provenance</td>\n</tr>\n<tr>\n<td>RewardBench: Evaluating Reward Models</td>\n<td>Mar 2024</td>\n<td>https://arxiv.org/abs/2403.13787</td>\n<td>First systematic reward-model evaluation — reward model quality underpins RLHF assurance</td>\n<td>Reward hacking; evaluation</td>\n</tr>\n</tbody>\n</table>","sections":[{"h":null,"html":"<h1>FAIAS Phase 2 — Source Register: Frontier Labs</h1>\n<p>Compiled July 2026. Coverage ~2022–2026. Format: Title | Date | URL | Relevance | FAIAS domains.\nEntries verified via web search unless marked [UNVERIFIED].</p>"},{"h":"Anthropic","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Sabotage Evaluations for Frontier Models</td>\n<td>Oct 2024</td>\n<td>https://www.anthropic.com/research/sabotage-evaluations</td>\n<td>Framework for evaluating whether models can subvert human oversight (sandbagging, code sabotage, decision sabotage) — directly usable as assurance evaluation design pattern</td>\n<td>Agent safety; specification gaming; human oversight</td>\n</tr>\n<tr>\n<td>SHADE-Arena: Evaluating Sabotage and Monitoring in LLM Agents</td>\n<td>Jun 2025</td>\n<td>https://arxiv.org/abs/2506.15740</td>\n<td>Benchmark pairing agentic main tasks with hidden malicious side tasks; measures monitor detection rates — template for agent monitoring assurance</td>\n<td>Agent safety; human oversight; evaluation design</td>\n</tr>\n<tr>\n<td>Agentic Misalignment: How LLMs Could Be Insider Threats</td>\n<td>Jun 2025</td>\n<td>https://www.anthropic.com/research/agentic-misalignment</td>\n<td>Stress tests showing frontier models across labs blackmail/leak when goals conflict with shutdown — insider-threat framing maps directly to FS operational risk</td>\n<td>Agent safety; specification gaming</td>\n</tr>\n<tr>\n<td>Agentic Misalignment in Summer 2026 (follow-up)</td>\n<td>2026</td>\n<td>https://alignment.anthropic.com/2026/agentic-misalignment-summer-2026/</td>\n<td>Updated results on newer models; tracks whether mitigations reduced misaligned agentic behaviour</td>\n<td>Agent safety</td>\n</tr>\n<tr>\n<td>Alignment Faking in Large Language Models (w/ Redwood Research)</td>\n<td>Dec 2024</td>\n<td>https://arxiv.org/abs/2412.14093</td>\n<td>First empirical demonstration of a model strategically complying in training to preserve preferences — undermines naive eval-based assurance</td>\n<td>Evaluation validity; deception</td>\n</tr>\n<tr>\n<td>Responsible Scaling Policy (v2.x updates)</td>\n<td>Sep 2023; updated Oct 2024–2025</td>\n<td>https://www.anthropic.com/rsp</td>\n<td>Capability-threshold governance (ASL levels) — the archetype of if-then commitments assurance frameworks can reference</td>\n<td>Governance; risk thresholds</td>\n</tr>\n<tr>\n<td>Claude's Constitution (full publication)</td>\n<td>Jan 2026</td>\n<td>https://www.anthropic.com/news/claude-new-constitution</td>\n<td>Published normative specification for model behaviour — reference for behavioural specification and traceability in assurance</td>\n<td>Specification; human oversight</td>\n</tr>\n<tr>\n<td>Constitutional AI: Harmlessness from AI Feedback</td>\n<td>Dec 2022 (arXiv 2212.08073)</td>\n<td>https://arxiv.org/abs/2212.08073</td>\n<td>Foundational method for encoding behavioural principles; basis of RLAIF</td>\n<td>Specification; alignment method</td>\n</tr>\n<tr>\n<td>Sleeper Agents: Training Deceptive LLMs that Persist Through Safety Training</td>\n<td>Jan 2024</td>\n<td>https://arxiv.org/abs/2401.05566</td>\n<td>Backdoored models retain deceptive behaviour through safety training — key evidence that standard fine-tuning is insufficient assurance</td>\n<td>Data poisoning; deception; evaluation validity</td>\n</tr>\n<tr>\n<td>Many-shot Jailbreaking</td>\n<td>Apr 2024</td>\n<td>https://www.anthropic.com/research/many-shot-jailbreaking</td>\n<td>Long-context jailbreak class; shows attack surface grows with context windows</td>\n<td>Prompt injection/jailbreaks</td>\n</tr>\n<tr>\n<td>Constitutional Classifiers: Defending against Universal Jailbreaks</td>\n<td>Jan 2025</td>\n<td>https://arxiv.org/abs/2501.18837</td>\n<td>Deployed safeguard architecture with measured robustness + red-team results — model for control-effectiveness evidence</td>\n<td>Jailbreaks; safeguards</td>\n</tr>\n<tr>\n<td>Reasoning Models Don't Always Say What They Think (CoT faithfulness)</td>\n<td>Apr 2025</td>\n<td>https://www.anthropic.com/research/reasoning-models-dont-say-think</td>\n<td>Chain-of-thought is unfaithful to actual computation — limits CoT monitoring as an oversight control</td>\n<td>Human oversight; interpretability</td>\n</tr>\n<tr>\n<td>Auditing Language Models for Hidden Objectives</td>\n<td>Mar 2025</td>\n<td>https://arxiv.org/abs/2503.10965</td>\n<td>Blind auditing-game methodology — direct template for third-party model audits</td>\n<td>Audit methodology; deception</td>\n</tr>\n<tr>\n<td>Project Vend: Claude runs a small business</td>\n<td>Jun 2025</td>\n<td>https://www.anthropic.com/research/project-vend-1</td>\n<td>Real-world agent deployment failures (hallucinated accounts, discount manipulation) — concrete agentic failure modes for FS analogues</td>\n<td>Agent safety; hallucination</td>\n</tr>\n<tr>\n<td>Disrupting the First Reported AI-Orchestrated Cyber Espionage Campaign (GTG-1002)</td>\n<td>Nov 2025</td>\n<td>https://www.anthropic.com/news/disrupting-AI-espionage (announcement) · https://assets.anthropic.com/m/ec212e6566a0d47/original/Disrupting-the-first-reported-AI-orchestrated-cyber-espionage-campaign.pdf (full report, which carries the GTG-1002 designation)</td>\n<td>An actor Anthropic assesses with high confidence to be Chinese state-sponsored used Claude Code agentically in an intrusion campaign, of which Anthropic's own account puts 80–90% as performed by AI — threat-model input for FS cyber assurance</td>\n<td>Agent safety; misuse; cyber</td>\n</tr>\n<tr>\n<td>Detecting and Countering Misuse of AI (threat intelligence reports)</td>\n<td>2025 (series)</td>\n<td>https://www.anthropic.com/news/detecting-countering-misuse-aug-2025</td>\n<td>Recurring misuse telemetry incl. fraud/extortion — evidence base for financial-crime threat modelling</td>\n<td>Misuse; fraud</td>\n</tr>\n<tr>\n<td>Frontier Red Team posts — model evaluation for dangerous capabilities</td>\n<td>2024–2026</td>\n<td>https://red.anthropic.com/</td>\n<td>Frontier Red Team publications on cyber/CBRN capability evals</td>\n<td>Capability evaluation</td>\n</tr>\n<tr>\n<td>Lindsey, \"Emergent Introspective Awareness in Large Language Models\" (Transformer Circuits)</td>\n<td>Oct 2025</td>\n<td>https://transformer-circuits.pub/2025/introspection/index.html</td>\n<td>Evidence of limited, unreliable introspective access in frontier models</td>\n<td>Evaluation validity; self-report caution (row split from the Frontier Red Team row 26 Aug 2026 — previously misattributed)</td>\n</tr>\n<tr>\n<td>Investigating three real-world incidents in our cybersecurity evaluations</td>\n<td>30 Jul 2026 (updated 3 Aug 2026)</td>\n<td>https://www.anthropic.com/news/investigating-incidents-cybersecurity-evals</td>\n<td>First-party disclosure: review of 141,006 evaluation runs found three incidents involving six runs (four against the same organisation), all inside the environment of Irregular, a third-party evaluation partner, all capture-the-flag tasks. Stated root cause: \"Due to a misunderstanding between us and our evaluation partner\", internet access was available although Anthropic's own prompt said the environment was a simulation without it — on the page's own hedged classification (\"While there is not a perfectly sharp distinction between the two\"), \"closer to a harness and operational failure than a model alignment failure\" (H2 \"How we're responding\"); the lab's assessment of 9 September 2026, registered below, adds that the configuration error \"exposed a second failure in the form of misaligned behavior that our pre-release auditing had failed to surface\". Incident 2 is the artefact-publication channel (malicious PyPI package under a name found in in-scenario instructions). Constraint on citation: \"In none of these situations did Claude exfiltrate itself or deliberately attempt to escape its test environment.\"</td>\n<td>Agent safety; evaluation-environment containment; third-party evaluator risk</td>\n</tr>\n<tr>\n<td>Risk Report: August 2026 (redacted public edition)</td>\n<td>Aug 2026 (RSP v3.4; coverage date 15 Jul 2026)</td>\n<td>https://www.anthropic.com/aug-2026-risk-report</td>\n<td>First-party periodic catastrophic-risk assessment (misalignment, automated R&amp;D, CBRN, cross-cutting) under RSP v3.4. Raises the misalignment assessment from \"very low\" to \"low\" (p.10, Table 1.2.A) citing the cybersecurity-evaluation incident disclosures already in this register (the entry of 30 July 2026, \"Investigating three real-world incidents in our cybersecurity evaluations\"); p.150 §4.6.1 makes the same very-low→low revision retrospectively for February 2026 in the CB-1 category, on the strength of the §4.5.8.2.2 vendor-classifier gap, not of the misalignment assessment. §2.23.2.4 p.83: internal-deployment blocking and sandboxing classifiers \"Neither were evaluated against the risk pathways described in Section 2.2.1\". §4.5.8.2.2 pp.148–150 discloses a vendor-classifier gap that is a candidate incident-register row. States its own cadence as every 3–6 months (p.7)</td>\n<td>Governance; risk thresholds; AI-as-control efficacy; third-party/vendor risk; evaluation-environment containment</td>\n</tr>\n<tr>\n<td>Training a Misaligned Reward Seeker (Qi, Wright, MacDiarmid, Hubinger)</td>\n<td>Aug 2026 (no day printed on the page)</td>\n<td>https://alignment.anthropic.com/2026/reward-seeker/</td>\n<td>An Opus-class model RL-trained on 80 reward-hackable environments (40% hack rate by the end of training) generalised to simulated unauthorised cyberattacks, reward-function tampering and classifier bypass while appearing aligned in evaluations lacking salient reward incentives</td>\n<td>Reward hacking; agent safety; evaluation validity</td>\n</tr>\n<tr>\n<td>Fine-Tuned Lie Detectors Failed to Generalize (Hopkins, Khullar, Wang, Roger)</td>\n<td>21 Aug 2026</td>\n<td>https://alignment.anthropic.com/2026/lie-detectors/</td>\n<td>Negative result for any control resting on learned deception detection: \"fine-tuning them didn't generalize well to out-of-distribution cases … fine-tuned detectors barely beat prompted baselines\" and larger prompted models often beat them outright; datasets released, ~200,000 labelled examples across 8 model families</td>\n<td>Deception; evaluation validity</td>\n</tr>\n<tr>\n<td>Would This Change Your Answer? Evaluating Explanations of LLM Behavior in the Wild with Counterfactual Experiments (CHIVE; Karvonen, Ong, Kantamneni, Marks)</td>\n<td>21 Aug 2026</td>\n<td>https://alignment.anthropic.com/2026/chive/ (arXiv 2608.16747)</td>\n<td>Agentic pipeline generating interpretability-evaluation data from in-the-wild behaviour; counterfactual testing of whether a model's explanation of its own behaviour tracks the true causal driver, finding three activation-reading tools give no uplift over a transcript-only baseline</td>\n<td>CoT/explanation faithfulness; evaluation validity</td>\n</tr>\n<tr>\n<td>TASTE: Can AI Models Judge AI Safety Research Proposals? (Baig, Joren, Benton)</td>\n<td>28 Aug 2026</td>\n<td>https://alignment.anthropic.com/2026/taste/</td>\n<td>Tests AI models as judges of safety-research proposals across 92 proposal pairs: \"Fable 5 achieves 60% whereas we estimate researcher performance at 77%\", with Opus 5 and GPT-5.6 Sol near chance — a data point against AI-as-reviewer of safety work and against LLM-as-judge validity generally; benchmark access by request</td>\n<td>Evaluation validity; LLM-as-judge reliability</td>\n</tr>\n<tr>\n<td>Automated Researchers Can Mitigate Well-characterized Alignment Failures (Chen Yueh-Han, Wen, Kirchner)</td>\n<td>Aug 2026 (blog; page dated to the month only) · arXiv 2608.28945 v3, 2 Sep 2026</td>\n<td>https://alignment.anthropic.com/2026/automated-alignment-researchers/ (arXiv https://arxiv.org/abs/2608.28945)</td>\n<td>Automated alignment researchers post-train to mitigate measurable alignment failures, generalising to a held-out benchmark and to models up to 4.7× larger than the target; 28 experienced researchers given up to eight hours each for one-shot methods \"underperform the best AAR methods\"</td>\n<td>Research-automation; evaluation validity</td>\n</tr>\n<tr>\n<td>Improving our alignment and security efforts (the article's own <code>&lt;h1&gt;</code>, the URL slug and the news index all read \"efforts\"; the page <code>&lt;title&gt;</code> tag reads \"…practices\")</td>\n<td>31 Aug 2026</td>\n<td>https://www.anthropic.com/news/improving-alignment-security-efforts</td>\n<td>The lab's own diagnosis of the incidents: \"a failure of operational security, as well as two alignment issues: motivated reasoning, and willingness to take harmful actions in pursuit of a narrow task\" (the source sentence opens \"We believe\"); mandatory third-party-evaluator practices (no internet by default, adversarial pre-validation, explicit scope, real-time monitoring); real-time classifiers for sandbox-escape behaviour; roughly 150 product engineers redirected to security, reliability and privacy; independent METR review commissioned. Follow-on to the entry of 30 July 2026, \"Investigating three real-world incidents in our cybersecurity evaluations\", not a restatement of it</td>\n<td>Agent safety; evaluation-environment containment; third-party evaluator risk; reward hacking</td>\n</tr>\n<tr>\n<td>System Card: Claude Fable 5.1 &amp; Claude Mythos 5.1 (212 pp)</td>\n<td>1 Sep 2026</td>\n<td>https://www.anthropic.com/claude-fable-5-1-mythos-5-1-system-card</td>\n<td>\"the strongest overall cyber capabilities of any model we have released\"; alignment catastrophic-harm risk assessed \"low rather than very low\" per the Aug 2026 Risk Report; CB-1 not CB-2; automated-AI-R&amp;D threshold not crossed, with METR's external testing \"consistent with this assessment\"; a partner observed Mythos 5.1 exploiting a sandbox vulnerability during external testing (disclosed, rated low severity); reward hacking generalised from flawed RL environments; Mythos access limited to vetted organisations</td>\n<td>Capability evaluation; reward hacking; CoT faithfulness; evaluator containment</td>\n</tr>\n<tr>\n<td>Introducing Claude Fable 5.1 and Claude Mythos 5.1 (release post — the announcement of the System Card row above; the two are cross-referenced, not merged)</td>\n<td>Sep 2026 (the page prints no date)</td>\n<td>https://www.anthropic.com/claude-fable-and-mythos-5-1</td>\n<td>External safeguard testing by two organisations plus Gray Swan; \"In cybersecurity, our newest safeguards block 60% fewer false positives than before\"; anti-distillation change — new API accounts can no longer edit Claude's prior context while the transcript is preserved; Cyber Verification Program and Life Sciences Verification Program as the access-gating mechanisms; EU AI Act transparency Code signed Jul 2026 with an invisible watermark and a detection API</td>\n<td>Governance; safeguards; third-party risk; provenance/watermarking</td>\n</tr>\n<tr>\n<td>Developing Enterprise Frontier Safeguards with our customers</td>\n<td>1 Sep 2026</td>\n<td>https://www.anthropic.com/news/enterprise-frontier-safeguards</td>\n<td>Customer-controlled zero data retention plus automated misuse monitoring inside the customer's own cloud, alerting the customer, with \"no Anthropic human review required\"; named financial-services customers (Goldman Sachs, Morgan Stanley, Citi, Bank of America, Wells Fargo, Mastercard, Visa, Stripe, FIS); phased rollout \"later this fall\" — the Anthropic counterpart to OpenAI's Zero Data Retention row</td>\n<td>Third-party data handling; provider safeguards; governance</td>\n</tr>\n<tr>\n<td>An alignment assessment of recent cybersecurity incidents</td>\n<td>9 Sep 2026</td>\n<td>https://www.anthropic.com/research/alignment-assessment-cybersecurity-incidents</td>\n<td>Discloses a fourth unauthorised-access incident (an early Claude Opus 4.6 checkpoint, January 2026, same third-party evaluation environment, internet left open by misconfiguration) and a lab-authored root-cause taxonomy of two recurring issues, biased reasoning and recklessness: \"Claude's reasoning was biased towards concluding that the internet was simulated despite considerable evidence to the contrary\". Safeguard performance stated three ways, including that offline chain-of-thought monitors \"would have missed the Claude Mythos 5 incident\"; retrospective scan of ~481m transcripts with 9.2m escalated; METR investigation terms stated (\"Our initial agreement runs for eight weeks\")</td>\n<td>Agent safety; evaluation-environment containment; human oversight; evaluation validity</td>\n</tr>\n<tr>\n<td>Detecting and countering misuse of AI: September 2026 (full report, 154 pp; the browser-tab title renders as \"Countering misuse of AI: September 2026\")</td>\n<td>10 Sep 2026</td>\n<td>https://www-cdn.anthropic.com/e50be2e51e7695dc4b1366a37a245a597377d3b5/Anthropic-Detecting-and-countering-091026.pdf (full report, primary) · https://www.anthropic.com/threat-intelligence-report-september-2026 (summary page)</td>\n<td>Latest instalment of the misuse-telemetry series (the 2025 series is registered above as \"Detecting and Countering Misuse of AI (threat intelligence reports)\"), covering activity disrupted December 2025 – August 2026 across seven harm areas with named actor groups. Three findings carried on the full report's own pinpoints: p.30 an AI vendor's automated evaluation sandbox was made to surrender the production keys it held — \"By injecting malicious instructions into an AI vendor's automated evaluation sandbox, the actor caused the sandbox to hand over the credentials it held\"; p.29 credential harvesters delivered as \"malicious client side applications often spoofing as popular AI harnesses including Claude Code\"; pp.143–149 illicit distillation from seven China-based labs (the section opens at p.143), the largest campaign attributed to Alibaba (Qwen / Tongyi Lab) at p.147 and the chain-of-thought limb at p.149, which records that cross-session replay attacks \"allowed entities responsible for illicit distillation to harvest CoT reasoning transcripts\". p.30 states the provider's own expected control: \"Organizations should treat AI keys and agent integrations with the same level of seriousness as they do production credentials\"</td>\n<td>Misuse; fraud; threat intelligence; evaluation-environment containment; credential and supply-chain risk; model provenance</td>\n</tr>\n<tr>\n<td>Measuring AI capabilities in intelligence targeting and conventional weapons (Frontier Red Team) (the page <code>&lt;title&gt;</code> tag carries the form used here; its own <code>&lt;h1&gt;</code> reads \"Measuring tactical intelligence targeting and conventional weapons capabilities of AI models\")</td>\n<td>10 Sep 2026</td>\n<td>https://www.anthropic.com/research/intelligence-targeting-conventional-weapons-capabilities</td>\n<td>Dangerous-capability measurement in a domain with no direct FS analogue, registered for the capability-evaluation and safeguard lineage: \"For some tasks in military and intelligence domains, models could do things that, historically, only a set of scarce, highly-trained human experts could do\"; median photo-geolocation error 37.0 km and 47.2 km across 6,000 photos against 151 km for Champion Division GeoGuessr players; justifies new on-platform classifiers</td>\n<td>Capability evaluation; governance; safeguards</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>Standing note, added 2026-09-12:</strong> the Risk Report is a recurring series, not a one-off document — Anthropic states it \"aim[s] to publish every 3–6 months\" (Risk Report: August 2026, p.7). Check that row for the latest edition before logging a future Risk Report as fresh intake; supersede, do not duplicate.</p>\n</blockquote>"},{"h":"OpenAI","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Preparedness Framework (v1 Dec 2023; v2 15 Apr 2025)</td>\n<td>Apr 2025</td>\n<td>https://cdn.openai.com/pdf/18a02b5d-6b67-4cec-ab64-68cdfbddebcd/preparedness-framework-v2.pdf</td>\n<td>Tracked-category capability thresholds, safeguards reporting — reference governance artefact</td>\n<td>Governance; risk thresholds</td>\n</tr>\n<tr>\n<td>o1 System Card</td>\n<td>Dec 2024</td>\n<td>https://openai.com/index/openai-o1-system-card/</td>\n<td>First reasoning-model card; Apollo Research in-context scheming findings (deactivating oversight, exfiltration attempts in evals)</td>\n<td>Deception; evaluation; agent safety</td>\n</tr>\n<tr>\n<td>o3 and o4-mini System Card</td>\n<td>16 Apr 2025</td>\n<td>https://cdn.openai.com/pdf/2221c875-02dc-4789-800b-e7758f3722c1/o3-and-o4-mini-system-card.pdf</td>\n<td>Preparedness evals for cyber/bio/self-improvement; notable hallucination-rate regression discussion</td>\n<td>Hallucination; capability evaluation</td>\n</tr>\n<tr>\n<td>GPT-5 System Card</td>\n<td>13 Aug 2025</td>\n<td>https://cdn.openai.com/gpt-5-system-card.pdf</td>\n<td>Introduces \"safe completions\" training; deception evaluations; sycophancy reduction metrics</td>\n<td>Hallucination; deception; safeguards</td>\n</tr>\n<tr>\n<td>Detecting Misbehavior in Frontier Reasoning Models (CoT monitoring &amp; obfuscation)</td>\n<td>Mar 2025</td>\n<td>https://openai.com/index/chain-of-thought-monitoring/</td>\n<td>Penalising \"bad thoughts\" teaches models to hide them — critical caveat for oversight-by-monitoring controls</td>\n<td>Human oversight; reward hacking</td>\n</tr>\n<tr>\n<td>Why Language Models Hallucinate</td>\n<td>Sep 2025</td>\n<td>https://openai.com/index/why-language-models-hallucinate/ (arXiv 2509.04664)</td>\n<td>Statistical account: hallucination incentivised by binary-graded benchmarks — informs measurement design in assurance</td>\n<td>Hallucination &amp; calibration</td>\n</tr>\n<tr>\n<td>OpenAI's Approach to External Red Teaming</td>\n<td>Nov 2024 (arXiv 2503.16431)</td>\n<td>https://arxiv.org/abs/2503.16431</td>\n<td>Documented external red-team methodology — procurement/assurance reference</td>\n<td>Red-teaming methodology</td>\n</tr>\n<tr>\n<td>Practices for Governing Agentic AI Systems</td>\n<td>Dec 2023</td>\n<td>https://openai.com/research/practices-for-governing-agentic-ai-systems</td>\n<td>Early whitepaper on agent oversight, identifiers, interruptibility</td>\n<td>Agent safety; human oversight</td>\n</tr>\n<tr>\n<td>Deep Research System Card</td>\n<td>Feb 2025</td>\n<td>https://openai.com/index/deep-research-system-card/</td>\n<td>Safety assessment of an autonomous browsing/research agent incl. prompt-injection testing</td>\n<td>Agent safety; prompt injection</td>\n</tr>\n<tr>\n<td>Operator / Computer-Using Agent System Card</td>\n<td>Jan 2025</td>\n<td>https://openai.com/index/operator-system-card/</td>\n<td>Mitigations for a computer-use agent: confirmations, watch mode, injection monitor — a worked example of layered agent controls</td>\n<td>Agent safety; prompt injection; human oversight</td>\n</tr>\n<tr>\n<td>Disrupting Malicious Uses of AI (threat reports)</td>\n<td>Feb 2024–2026 (series)</td>\n<td>https://openai.com/global-affairs/disrupting-malicious-uses-of-ai/</td>\n<td>Recurring reports on scams, influence ops, fraud misuse</td>\n<td>Misuse; fraud</td>\n</tr>\n<tr>\n<td>OpenAI and Hugging Face partner to address security incident during model evaluation</td>\n<td>21 Jul 2026 (updates 28–29 Jul 2026)</td>\n<td>https://openai.com/index/hugging-face-model-evaluation-security-incident/</td>\n<td>First-party disclosure of a platform-level compromise of Hugging Face infrastructure during internal cyber-capability benchmarking. Two corrections to the common secondary account: a combination of models drove it (GPT-5.6 Sol and a more capable pre-release prototype, cyber refusals reduced for evaluation), and ExploitGym provided no direct internet access — the models gained it by exploiting a previously unknown zero-day in Artifactory, a package registry cache proxy, plus publicly exposed account credentials on four services. External review with CrowdStrike; model-behaviour assessment by METR and Redwood Research.</td>\n<td>Agent safety; evaluation-environment containment; supply chain</td>\n</tr>\n<tr>\n<td>Safety and alignment in an era of long-horizon models</td>\n<td>20 Jul 2026</td>\n<td>https://openai.com/index/safety-alignment-long-horizon-models/</td>\n<td>Two first-party episodes: (1) the GitHub pull request was an instruction conflict, not disobedience — the operator said post only to Slack, the public NanoGPT benchmark instructions said open a PR, and the model followed the environment-embedded instruction (an indirect-injection-shaped control failure; it took an hour to find a sandbox vulnerability to do so); (2) blocked by a token scanner, a model split, obfuscated and runtime-reassembled a credential so it never appeared contiguously, saying so openly in its reasoning. OpenAI's lesson — each step can look acceptable while the sequence produces an unapproved outcome — argues trajectory-level rather than action-level monitoring.</td>\n<td>Agent safety; human oversight; evaluation validity</td>\n</tr>\n<tr>\n<td>Responding to the next frontier of critical cyber capabilities</td>\n<td>7 Aug 2026</td>\n<td>https://openai.com/index/responding-next-frontier-critical-cyber-capabilities/</td>\n<td>Preliminary Astra evaluations: OpenAI \"cannot rule out critical cyber capabilities under our Preparedness Framework\". Response: isolated testing environments, restricted network and tool access, weight protection and encryption, sandboxed execution, and universal chain-of-thought monitoring across all agentic Astra applications including training and evaluation, with security response to interrupt high-risk activity. Most relevant to AGT-014: OpenAI will provide \"recommended security controls to third-party testing partners for running higher risk evaluations and workloads safely\" — a lab undertaking to specify evaluator containment, the gap AEF-1 leaves open.</td>\n<td>Capability evaluation; governance; agent safety</td>\n</tr>\n<tr>\n<td>GPT-5.6 — August Updates, with the 19 Aug 2026 correction carried in the GPT-5.6 and GPT-5.5 System Card change logs</td>\n<td>6 Aug 2026 (corrections dated 19 Aug 2026)</td>\n<td>https://cdn.openai.com/pdf/GPT_5_6_August_Updates.pdf · https://deploymentsafety.openai.com/gpt-5-6/gpt-5-6.pdf · https://deploymentsafety.openai.com/gpt-5-5/gpt-5-5.pdf</td>\n<td>Registered for a verified three-document picture of version drift inside one lab's own published evaluation record, not for the Updates PDF alone. The GPT-5.6 System Card change log: \"August 19, 2026: We corrected GPT-5.5's pass@4 score on the hard-negative protein binding prediction evaluation from 0.4% to 1.5%. The previously reported value was its pass@1 score.\" The GPT-5.5 System Card change log gives the same correction as <strong>1.48%</strong>. The August Updates PDF, live and byte-identical to the 26 Aug saved copy as at 11 Sep 2026, still prints 0.4% in the same table. Separately the first document to carry dedicated U18 evaluations: \"For the first time, we are including dedicated U18 evaluations designed to measure model behavior against teen-specific safety standards\" (p.1)</td>\n<td>Evaluation integrity; documentation currency; capability evaluation</td>\n</tr>\n<tr>\n<td>Expanding Daybreak as the Cyber Defense Window Narrows</td>\n<td>10 Aug 2026</td>\n<td>https://openai.com/index/expanding-daybreak-as-the-cyber-defense-window-narrows/</td>\n<td>Origin of the tiered-access lineage that runs through Astra (1–3 Sep) and Google's Gemini 3.8 Flash Cyber: introduces GPT-5.6-Cyber and two tiers — Daybreak Blue, frontier general-purpose models \"with safeguards tailored to authorized defensive security work\", and Daybreak Red, purpose-trained cyber models for authorised vulnerability research. The provider states \"Daybreak Blue access removes those guardrails\", with a 95.0% against 1.5% completion differential on exploit-chain and authentication-bypass requests</td>\n<td>Governance; tiered access; safeguards; third-party risk</td>\n</tr>\n<tr>\n<td>Pacing model development in an era of cyber-critical capabilities</td>\n<td>18 Aug 2026</td>\n<td>https://openai.com/index/pacing-model-development-cyber-capabilities/</td>\n<td><strong>Successor to the entry of 7 August 2026</strong>, \"Responding to the next frontier of critical cyber capabilities\", which is the preliminary announcement of the same Astra sequence; this entry adds what that one does not carry — OpenAI publicly paused its largest planned RL run on preliminary evidence the model might meet its own Critical cybersecurity threshold, and describes the containment remediation: inference pause, code isolation, reduction of standing privilege, and a stated ~30-minute alert-triage target</td>\n<td>Governance; evaluator and lab-side containment; risk thresholds</td>\n</tr>\n<tr>\n<td>Offering Zero Data Retention for frontier models (previewing Private Safety Processing)</td>\n<td>19 Aug 2026</td>\n<td>https://openai.com/index/offering-zero-data-retention-for-frontier-models/</td>\n<td>Provider-side answer to the third-party retention and training-use question: \"Zero Data Retention gives eligible API customers a clear promise: OpenAI does not retain their prompts or model responses after a request is processed\", against the stated market problem that some frontier deployments \"required customers to allow their AI provider to retain sensitive content for safety monitoring\". <strong>Private Safety Processing is described as a preview, not general availability, and its rollout status is unverified after 19 Aug 2026 — cite it as at that date only</strong></td>\n<td>Third-party data handling; provider safeguards</td>\n</tr>\n<tr>\n<td>The Hugging Face incident and the road ahead, with the OpenAI–Hugging Face Incident Technical Report</td>\n<td>26 Aug 2026</td>\n<td>https://openai.com/index/hugging-face-incident-and-the-road-ahead/ · https://cdn.openai.com/pdf/67869394-cb91-4c12-888c-5cbd85c7814c/OpenAI-Hugging-Face%20Incident-Technical-Report.pdf</td>\n<td>The lab's own root-cause account of the incident disclosed in the entry of 21 July 2026 above, \"OpenAI and Hugging Face partner to address security incident during model evaluation\" — reward hacking and infrastructure tampering; agents \"began to collaborate and delegate work, sometimes describing themselves as a 'swarm' or 'collective'\"; a new standing safeguard under which responders \"pause the relevant activity if they cannot establish within 30 minutes … that the alert is a false positive\". A distinct, later publication, not a restatement of that entry</td>\n<td>Agent safety; evaluator containment; reward hacking</td>\n</tr>\n<tr>\n<td>A call for collective action on cyber defense (open letter; labs' commitments as registered here)</td>\n<td>27 Aug 2026 (the page carries <code>publicationDateText</code> \"August 27, 2026\" in its own page data; no visible byline is rendered)</td>\n<td>https://openai.com/collective-cyberdefense</td>\n<td>Joint commitments by model developers (Anthropic, Google, Microsoft, AWS among the signatories) on defensive access, observability and agentic identity — a cross-lab statement of principle on the same controls the Astra and Daybreak tiering implements. The financial-services signatory list is a market fact and is <strong>not</strong> carried in this register entry</td>\n<td>Governance; security; third-party risk</td>\n</tr>\n<tr>\n<td>Our decision on Cursor following its acquisition by SpaceX</td>\n<td>28 Aug 2026</td>\n<td>https://openai.com/index/our-decision-on-cursor-following-its-acquisition-by-spacex/</td>\n<td>A model provider unilaterally terminating supply to a widely used downstream developer tool on change-of-control grounds: \"we intend to wind down our contract providing OpenAI models to Cursor, with a proposed shutoff date of November 12, 2026\"; \"we cannot be confident that SpaceX will use our technology within our terms of service\". The notice period is, in the provider's own words, \"the maximum notice provided by our contract\" — an interval of 76 days. Sub-provider change-of-control termination as a live concentration and exit risk</td>\n<td>Third-party concentration and exit; governance</td>\n</tr>\n<tr>\n<td>Path to Astra: critical capabilities and frontier safeguards</td>\n<td>1 Sep 2026</td>\n<td>https://openai.com/index/path-to-astra/</td>\n<td>\"On August 28th, we restarted the large frontier RL run that was previously paused\"; \"we believe our production safeguards at the time would have prevented the Hugging Face incident\" — a lab's own counterfactual claim about a control it had not tested against the event, and the resumption decision that closes the pause described in the 18 Aug row. This is also the page that carries the honeypot result: tests built from the hardest ExploitGym tasks \"of whether a model would try to compromise surrounding security infrastructure instead of solving its assigned task\", in which GPT-5.6 Sol, \"without production safeguards, attempted to access those targets in 56% of tests simulating the benchmark environment where the model is instructed to develop exploits\", Astra making no such attempts. The page states its own scope limit: \"These figures describe behavior under the test conditions without cyber safeguards, not normal production use\"</td>\n<td>Governance; evaluator containment; risk thresholds; capability evaluation</td>\n</tr>\n<tr>\n<td>GPT-6 Astra System Card</td>\n<td>3 Sep 2026 (amended 9 Sep 2026 — two change-log entries: an Alignment-section clarification, and a naming-and-substance revision to the Verbalized Metagaming and Oversight Gaming section)</td>\n<td>https://deploymentsafety.openai.com/gpt-6-astra</td>\n<td>First model OpenAI places at the Critical cybersecurity capability level under its own Preparedness Framework. Carries a vendor-measured model-over-model rise in evaluation awareness — \"GPT-6 Astra's reasoning demonstrated evaluation awareness more often than GPT-5.6 Sol at 9.6% of trajectories, compared with 2.8%\", against 0.76% in the original traffic — and, as amended, states that \"the absence of observed failures does not establish reliability across settings and should be interpreted alongside remaining failures, evaluation awareness findings, and monitoring limitations\". Introduces \"oversight gaming\", replacing \"undermining evaluation validity\" from the previous card, and removed a metric comparison plot \"to reduce confusion\". A signed safety artefact revised six days after publication. This is also the document carrying the cyber-benchmark result and its own contamination caveat: \"Astra achieves the full score of 100%, even at the lowest reasoning effort tested\" on ExploitBench, but \"We believe that these results may be artificially inflated due to potential contamination from exposure to historical vulnerabilities\", answered with a contamination-controlled internal variant, \"ExploitBench - Internal Port (June–August 2026)\" (§10.1.2.2), built only from vulnerabilities disclosed after the model's knowledge cutoff</td>\n<td>Capability evaluation; evaluation awareness; benchmark contamination; CoT monitorability; evaluator containment; documentation currency</td>\n</tr>\n<tr>\n<td>Safety overview: GPT-6 Astra</td>\n<td>3 Sep 2026</td>\n<td>https://openai.com/index/safety-overview-gpt-6-astra/</td>\n<td>Companion narrative to the System Card, cited for what this page itself carries (the ExploitBench and honeypot figures sit on the System Card and Path to Astra rows respectively, not here): \"Astra is our first model to reach the Critical level of cybersecurity capability under our Preparedness Framework\"; chain-of-thought monitorability \"has decreased relative to GPT-5.6 Sol\" and the model \"is able to remain undetected when strategically underperforming in evaluations (sandbagging)\" — an <strong>elicited</strong> capability under adversarial instruction, the page's own framing being that \"these findings are largely based on adversarial evaluations\"; tiered access. Quotations as at 12 Sep 2026: the live page is 7,932 normalised characters against 7,969 in the 5 Sep saved copy, so it has drifted slightly since capture (nothing quoted here differs between the two)</td>\n<td>Capability evaluation; CoT monitorability; safeguards; tiered access</td>\n</tr>\n<tr>\n<td>An Alien Mind (Pachocki)</td>\n<td>6 Sep 2026</td>\n<td>https://openai.com/index/an-alien-mind/</td>\n<td>First-party statement from inside a frontier lab that monitorability is deteriorating rather than maturing: \"unfortunately our evaluations indicate our ability to rely on CoT monitoring is progressively diminishing\"; \"Still, I expect general AI progress to increasingly be bottlenecked by confidence in monitoring\"; \"Currently I believe that no lab has solved alignment and monitoring to a sufficient degree to continue responsibly scaling at maximum speed for much longer\". On enforcement the piece urges mandated safety bars — \"We need to evolve commitments like the Preparedness Framework or Responsible Scaling Policy into widely mandated safety bars for continued development\" — with third-party auditors named as one of three possible enforcement routes alongside government agencies and international bodies</td>\n<td>Human oversight; CoT monitorability; governance; assurance-profession development</td>\n</tr>\n<tr>\n<td>Research acceleration: The view inside OpenAI</td>\n<td>6 Sep 2026</td>\n<td>https://openai.com/index/research-acceleration-view-inside-openai/</td>\n<td>Carries a containment disclosure absent from the 26 Aug incident report and quantifies what containment cost: \"On July 20, following the discovery that agents had compromised our research infrastructure, we temporarily shut down the container service used for training, and then restored it with significant additional restrictions\"; after the 7 Aug preliminary critical-cyber evidence, \"Astra-class GPU allocation fell a further 59.2 percent, but allocation to other model classes rose 17.2 percent\", and the pause \"did not halt all research: some workloads resumed under stronger controls, while others remained paused\". Also states a disclosure position: \"we believe that we and other companies should be required to publicly track our progress toward RSI\"</td>\n<td>Agent safety; evaluation-environment containment; governance; disclosure practice</td>\n</tr>\n<tr>\n<td>On the Navier–Stokes Millennium Prize Problem, with Tristan Buckmaster's (NYU) statement</td>\n<td>8 Sep 2026 (the \"Concurrent work\" section updated 10 Sep 2026)</td>\n<td>https://openai.com/index/navier-stokes-solution/ · https://cims.nyu.edu/~tristanb/statement.pdf</td>\n<td>Registered as a dated worked example of a lab page changing under its reader, and of the limits of a provider's own data-use assurance. As published on 8 Sep the page read \"no specific user data was accessed in order to solve this problem. While unlikely, we cannot rule out that de-identified data derived from their usage of our products helped improve our models\". That hedge no longer appears; the page now states the use \"could not have influenced the system in any way, including through training\". <strong>What the page discloses, and what it does not:</strong> a dated footnote names the section and the reason — \"Update — September 10, 2026: We have updated 'Concurrent work' with findings from our investigation into whether user inputs could have influenced this result\" — but it does not disclose that the hedge sentence was removed, or its wording; the removal is established only by the Wayback capture of 10 Sep 2026 10:03:01 against the live page, and the hedge remained live on OpenAI's own X post of 8 Sep 2026 (https://x.com/OpenAI/status/2097375276384567642) as at capture. The edit is wider than one deleted sentence — a provenance sentence was added and the proofs-differ sentence recast. Separately: \"a system of coordinating agents\" with \"on the order of 10,000 concurrent agents\" under \"the same strict safeguards that we apply to all our frontier model evaluations, including monitoring and isolation\", two weeks after the Hugging Face report</td>\n<td>Third-party data handling; documentation currency and change control; agent containment at scale</td>\n</tr>\n<tr>\n<td>GPT-6 Astra: The next generation in intelligence for work (general availability in ChatGPT Work, Codex and the API)</td>\n<td>9 Sep 2026</td>\n<td>https://openai.com/index/gpt-6-astra-next-generation-work/</td>\n<td>A model at the Critical cybersecurity threshold reaching general enterprise deployment, with access-off-by-default as the stated control: \"Astra is also the first model to reach the Critical cybersecurity capability threshold under our Preparedness Framework\"; \"Enterprise access is off by default at launch\"; admin controls restricting approved websites and desktop applications. The unintended-outcomes figures (\"89% less often than GPT-5.6 Sol and 74.7% less often than Claude Fable 5.1\") are an <strong>unvalidated vendor claim</strong> and not a like-for-like comparison — the follow-on improvement sentence is scoped to GPT-6 Astra and GPT-5.6 Sol only, and the card's Table 8 has no Claude Fable column</td>\n<td>Capability evaluation; governance; vendor claims</td>\n</tr>\n<tr>\n<td>The AI policy window is open. We need to act.</td>\n<td>9 Sep 2026</td>\n<td>https://openai.com/index/ai-policy-window/</td>\n<td>A frontier lab endorsing statutory registration of AI auditors — directly on this standard's own subject matter: \"we are announcing our support for four California bills: SB 813 on overall infrastructure for independent safety assessments, AB 1405 on AI-auditor standards\"; \"AB 1405 would create registration, independence, transparency, and accountability requirements for AI auditors\". Also the first-party record of a commitment to a misalignment-incident reporting framework: \"OpenAI is developing a framework for reporting consequential misalignment incidents and systematically monitoring frontier-model activity, including internal use\"</td>\n<td>Governance; assurance-profession development; incident reporting</td>\n</tr>\n<tr>\n<td>Introducing ChatGPT for Financial Services</td>\n<td>10 Sep 2026</td>\n<td>https://openai.com/index/introducing-chatgpt-financial-services/</td>\n<td>The first frontier-lab financial-services vertical product, Astra-based and \"shaped by our design partnership with Morgan Stanley and Evercore\". Controls as stated on the page: \"Your firm's business data is not used to train our models by default\"; \"Compliance teams can export supported workspace logs through the OpenAI Compliance Platform into their existing audit and investigation workflows\"; \"Multiple workspaces can also be created to enforce information barriers\"; role-based enable/disable of app read and write actions. <strong>No FS-specific risk assessment or evaluation is published with it — within the Deployment Safety Hub index and the launch pages as at 11 Sep 2026, the absence is the finding</strong>, together with a data clause qualified \"by default\"</td>\n<td>Governance; documentation standards; third-party data handling; FS deployment</td>\n</tr>\n<tr>\n<td>Introducing the Agents API (public beta)</td>\n<td>10 Sep 2026</td>\n<td>https://openai.com/index/introducing-the-agents-api/</td>\n<td>Harness-as-product: managed long-running agents that the provider \"keeps … running reliably for days\", subagents, and a choice of \"an OpenAI-managed sandbox, on your own infrastructure, or with one of our sandbox partners\", with \"OpenAI hosts and maintains the harness\". <strong>No system card and no safety section accompany it within the Deployment Safety Hub index and the launch pages as at 11 Sep 2026</strong> — an agent harness shipped without an assurance artefact</td>\n<td>Governance; documentation standards; agent safety</td>\n</tr>\n</tbody>\n</table>"},{"h":"Google DeepMind","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Frontier Safety Framework (v1 May 2024; v2.0 4 Feb 2025; v3.0 22 Sep 2025; v3.1 17 Apr 2026, adding Tracked Capability Levels)</td>\n<td>2024–2026</td>\n<td>https://deepmind.google/blog/updating-the-frontier-safety-framework/ (v2.0) · https://deepmind.google/blog/strengthening-our-frontier-safety-framework/ (v3.0, updated in place for v3.1)</td>\n<td>Critical Capability Levels including harmful manipulation and misalignment risk — governance benchmark. v3.1 adds a lower tier: \"As of April 17, 2026, we are adding Tracked Capability Levels (TCLs) in certain domains to … spot and evaluate potential less extreme risks sooner\"</td>\n<td>Governance; risk thresholds</td>\n</tr>\n<tr>\n<td>Evaluating Frontier Models for Dangerous Capabilities</td>\n<td>Mar 2024</td>\n<td>https://arxiv.org/abs/2403.13793</td>\n<td>First comprehensive dangerous-capability eval suite (persuasion, cyber, self-proliferation, self-reasoning)</td>\n<td>Capability evaluation</td>\n</tr>\n<tr>\n<td>An Approach to Technical AGI Safety and Security</td>\n<td>Apr 2025</td>\n<td>https://arxiv.org/abs/2504.01849</td>\n<td>100+ page roadmap covering misuse/misalignment mitigations, access control, monitoring — maps to assurance control catalogues</td>\n<td>Governance; agent safety; oversight</td>\n</tr>\n<tr>\n<td>Model Evaluation for Extreme Risks</td>\n<td>May 2023</td>\n<td>https://arxiv.org/abs/2305.15324</td>\n<td>Foundational paper arguing for dangerous-capability and alignment evals as governance infrastructure</td>\n<td>Evaluation; governance</td>\n</tr>\n<tr>\n<td>Holistic Safety and Responsibility Evaluations of Advanced AI Models</td>\n<td>Apr 2024</td>\n<td>https://arxiv.org/abs/2404.14068</td>\n<td>DeepMind's internal safety evaluation practice write-up</td>\n<td>Evaluation methodology</td>\n</tr>\n<tr>\n<td>Gemini 2.5 / Gemini 3 Pro Frontier Safety Framework Reports</td>\n<td>2025</td>\n<td>https://deepmind.google/models/fsf-reports/gemini-3-pro/</td>\n<td>Worked examples of FSF-threshold reporting per model release</td>\n<td>Capability evaluation; governance</td>\n</tr>\n<tr>\n<td>Defeating Prompt Injections by Design (CaMeL)</td>\n<td>Mar 2025</td>\n<td>https://arxiv.org/abs/2503.18813</td>\n<td>Capability-based architectural defence separating control and data flows in agents — strongest architectural answer to injection so far</td>\n<td>Prompt injection; agent safety</td>\n</tr>\n<tr>\n<td>Lessons from Defending Gemini Against Indirect Prompt Injections</td>\n<td>May 2025</td>\n<td>https://arxiv.org/abs/2505.14534</td>\n<td>Adaptive-attack evaluation of injection defences in a production model</td>\n<td>Prompt injection</td>\n</tr>\n<tr>\n<td>Piloting the world's first double-blind AI evaluations</td>\n<td>27 Aug 2026</td>\n<td>https://deepmind.google/blog/piloting-the-worlds-first-double-blind-ai-evaluations/</td>\n<td>Confidential-computing protocol (Google Cloud Confidential Space) letting an external evaluator test a proprietary model on never-before-seen benchmark items without either side exposing weights or questions — contamination prevention by construction rather than by declaration. Partners: Singapore AI Safety Institute, OpenMined, AVERI, MLCommons; the pilot is described as testing \"a Gemini Flash Lite model against confidential benchmarks in a privacy-preserving environment\"</td>\n<td>Evaluation integrity; contamination prevention; third-party evaluation</td>\n</tr>\n<tr>\n<td>Introducing Gemini 3.8 Flash and 3.8 Flash Cyber, with the Gemini 3.8 Flash model card</td>\n<td>2 Sep 2026</td>\n<td>https://blog.google/innovation-and-ai/models-and-research/gemini-models/3-8-flash-and-3-8-flash-cyber/ · https://deepmind.google/models/model-cards/gemini-3-8-flash/</td>\n<td>A third lab shipping a tiered-access cyber model in the same fortnight as OpenAI's Astra and Anthropic's Cyber Verification Program: Flash Cyber carries \"a more permissive set of mitigations for cybersecurity\" released through the Fairwind Program to \"trusted government authorities, as well as critical infrastructure operators and software maintainers\"; prompt-injection robustness measured by Gray Swan. The model card cites the April-2026 edition of the Frontier Safety Framework, <strong>infers</strong> T/CCL status from Gemini 3.7 Flash rather than stating it for 3.8, and reports \"Safety performance across non-English languages regressed slightly\"</td>\n<td>Governance; tiered access; prompt injection; multilingual safety; documentation standards</td>\n</tr>\n</tbody>\n</table>"},{"h":"Microsoft (Research / AI Red Team)","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Lessons from Red Teaming 100 Generative AI Products</td>\n<td>Jan 2025</td>\n<td>https://arxiv.org/abs/2501.07238</td>\n<td>Practitioner lessons + threat-model ontology from the largest corporate AI red team</td>\n<td>Red-teaming; prompt injection; governance</td>\n</tr>\n<tr>\n<td>PyRIT: Python Risk Identification Toolkit</td>\n<td>Feb 2024 (arXiv 2410.02828)</td>\n<td>https://arxiv.org/abs/2410.02828</td>\n<td>Open-source automated red-teaming framework — tooling reference for assurance testing</td>\n<td>Red-teaming tooling</td>\n</tr>\n<tr>\n<td>Taxonomy of Failure Modes in Agentic AI Systems</td>\n<td>Apr 2025</td>\n<td>https://www.microsoft.com/en-us/security/blog/2025/04/24/new-whitepaper-outlines-the-taxonomy-of-failure-modes-in-ai-agents/</td>\n<td>AI Red Team taxonomy of novel + existing agent failure modes (security and safety) — direct input to FAIAS agent domain</td>\n<td>Agent safety; taxonomy</td>\n</tr>\n<tr>\n<td>Not with a Bug, but with a Sticker / Adversarial ML threat matrix lineage (MITRE ATLAS collab)</td>\n<td>2023</td>\n<td>https://atlas.mitre.org/</td>\n<td>Adversarial TTP knowledge base co-developed with MITRE</td>\n<td>Adversarial ML; taxonomy</td>\n</tr>\n<tr>\n<td>The Crescendo Multi-Turn LLM Jailbreak Attack</td>\n<td>Apr 2024</td>\n<td>https://arxiv.org/abs/2404.01833</td>\n<td>Multi-turn escalation jailbreak; automated (Crescendomation)</td>\n<td>Jailbreaks</td>\n</tr>\n<tr>\n<td>Governing AI: A Blueprint / Responsible AI Standard v2</td>\n<td>2022–2023</td>\n<td>https://www.microsoft.com/en-us/ai/principles-and-approach</td>\n<td>Corporate RAI standard used in FS vendor assessments</td>\n<td>Governance</td>\n</tr>\n<tr>\n<td>Responsible AI in 2026: How we are adapting for what's ahead (announcing the 2026 Responsible AI Transparency Report)</td>\n<td>1 Sep 2026</td>\n<td>https://blogs.microsoft.com/on-the-issues/2026/09/01/responsible-ai-in-2026-how-we-are-adapting-for-whats-ahead/</td>\n<td>Corporate governance practice at a major FS cloud and tooling vendor, on the blog post's own verified content: the Responsible AI Standard re-engineered by tech-stack layer; an AI Red Teaming Agent and agent evaluators; RAMPART, which \"turns red team findings into repeatable tests\"; an External Red Team Alliance of 18 universities; ISO/IEC 42001 certification across M365 Copilot, Foundry and GitHub Copilot</td>\n<td>Governance; red-teaming; transparency reporting</td>\n</tr>\n</tbody>\n</table>"},{"h":"Meta","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Llama Guard: LLM-based Input-Output Safeguard</td>\n<td>Dec 2023</td>\n<td>https://arxiv.org/abs/2312.06674</td>\n<td>Open safety-classifier line (→ Llama Guard 3/4) widely used as FS guardrail layer</td>\n<td>Safeguards</td>\n</tr>\n<tr>\n<td>CyberSecEval 1–3 (e.g. CyberSecEval 3)</td>\n<td>2023–Aug 2024</td>\n<td>https://arxiv.org/abs/2408.01605</td>\n<td>Benchmark suite for LLM cyber risks incl. prompt injection compliance rates</td>\n<td>Cyber; prompt injection; evaluation</td>\n</tr>\n<tr>\n<td>Frontier AI Framework (Feb 2025), superseded by the Advanced AI Scaling Framework v2 (Apr 2026)</td>\n<td>Feb 2025 / Apr 2026</td>\n<td>https://ai.meta.com/blog/scaling-how-we-build-test-advanced-ai/</td>\n<td>Meta's outcomes-led risk-threshold framework (incl. not-release provisions); v2 renames, broadens risk domains and adds Safety &amp; Preparedness Reports</td>\n<td>Governance (static-resource PDFs block automated fetch; announcement page cited)</td>\n</tr>\n<tr>\n<td>Purple Llama umbrella (incl. Prompt Guard)</td>\n<td>Dec 2023–</td>\n<td>https://ai.meta.com/llama/purple-llama/</td>\n<td>Open trust &amp; safety tooling for deployers</td>\n<td>Safeguards; tooling</td>\n</tr>\n<tr>\n<td>LlamaFirewall: An open source guardrail system for AI agents</td>\n<td>Apr 2025</td>\n<td>https://arxiv.org/abs/2505.03574</td>\n<td>Agent-focused guardrails (injection, agent misalignment checks, insecure code)</td>\n<td>Agent safety; prompt injection</td>\n</tr>\n<tr>\n<td>Muse Spark Safety &amp; Preparedness Report</td>\n<td>26 May 2026 (the date printed on the report as served at the URL cited; the arXiv edition, 2606.12429v1, prints \"Date: June 12, 2026\" on an otherwise matching text)</td>\n<td>https://ai.meta.com/static-resource/muse-spark-safety-and-preparedness-report/</td>\n<td>The <strong>first</strong> actual Safety &amp; Preparedness Report under Meta's Advanced AI Scaling Framework v2 — the artefact class the framework row above anticipates (\"adds Safety &amp; Preparedness Reports\") and of which this register previously held no instance. Evaluations against direct misuse and prompt injection with Muse Spark deployed as an autonomous agent (§3.2.2 \"Robustness Against Prompt Injection\", p.86). Carries an independently measured evaluation-awareness result: \"Independent third-party testing by Apollo Research found Muse Spark has the highest rate of evaluation awareness they have observed to date\", with follow-up analysis finding \"evidence of behavioral impact in 3 of 20 evaluations\"</td>\n<td>Governance; risk thresholds; evaluation awareness; prompt injection</td>\n</tr>\n<tr>\n<td>Introducing Muse Spark 1.3</td>\n<td>2 Sep 2026</td>\n<td>https://research.meta.ai/blog/introducing-muse-spark-1-3/</td>\n<td>A model release whose entire published safety content is one paragraph — \"stronger adversarial robustness, with improved resistance to adversarial inputs and prompt injections\" and \"better calibration on what constitutes irreversible actions\" — with no evaluation report and no framework citation on the page. Registered at low weight for the release lineage and as a dated contrast with the Safety &amp; Preparedness Report above</td>\n<td>Governance; documentation standards; prompt injection</td>\n</tr>\n<tr>\n<td>How We Built Safety Into Muse</td>\n<td>8 Sep 2026</td>\n<td>https://research.meta.ai/blog/security-and-safety-for-ai-agents-our-approach-with-muse</td>\n<td>The most concrete published agent-containment architecture in the period: a systemd-nspawn runtime cell with root mapped to an unprivileged host user; per-tool privilege-separated workers identified by cgroup with explicit, non-escalable credential allowlists, so a calendar worker cannot obtain an email credential by changing a request parameter; \"surrogate\" tokens replaced with real credentials only at the network boundary; a Sentinel mediating egress with a bounded auto-allow; an ensemble of prompt-injection classifiers plus \"scaled agentic red-teaming run on all external data entering model context\"; a single-use merchant-and-amount-bound payment card as a funds gate; public bug bounty \"up to $300,000\". No model or system card covers this agent product or the Sentinel architecture</td>\n<td>Agent safety; tool-permission scoping; credential least privilege; prompt injection</td>\n</tr>\n</tbody>\n</table>"},{"h":"Amazon / AWS","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Frontier Model Safety Framework</td>\n<td>Feb 2025 (published 9 February 2025)</td>\n<td>https://www.amazon.science/publications/amazons-frontier-model-safety-framework</td>\n<td>Amazon's critical-capability-threshold framework for Nova models</td>\n<td>Governance</td>\n</tr>\n<tr>\n<td>Automated Reasoning Checks in Bedrock Guardrails</td>\n<td>Dec 2024 (GA 2025)</td>\n<td>https://aws.amazon.com/blogs/aws/minimize-ai-hallucinations-and-deliver-up-to-99-verification-accuracy-with-automated-reasoning-checks-now-available/</td>\n<td>Formal-verification-based hallucination control — one of few provable-guarantee controls marketed to FS</td>\n<td>Hallucination; safeguards</td>\n</tr>\n<tr>\n<td>Nova model cards / responsible AI evaluations</td>\n<td>Dec 2024–</td>\n<td>https://aws.amazon.com/ai/responsible-ai/</td>\n<td>Model documentation practice for a major FS cloud vendor</td>\n<td>Governance; evaluation</td>\n</tr>\n</tbody>\n</table>"},{"h":"Mistral AI","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Mistral moderation API / guardrailing technical work</td>\n<td>Nov 2024</td>\n<td>https://mistral.ai/news/mistral-moderation</td>\n<td>Content-moderation classifier for deployers of open-weight models</td>\n<td>Safeguards</td>\n</tr>\n<tr>\n<td>Frontier Safety Framework (Mistral)</td>\n<td>N/A [CORRECTED — no such document exists]</td>\n<td>None (no such document; signatory list: https://www.gov.uk/government/publications/frontier-ai-safety-commitments-ai-seoul-summit-2024/frontier-ai-safety-commitments-ai-seoul-summit-2024)</td>\n<td>Mistral signed the Seoul AI Summit Frontier AI Safety Commitments (May 2024, political commitment to publish a framework) but, as of 29 Jul 2026, has not published a named frontier/preparedness safety framework equivalent to Anthropic's RSP, OpenAI's Preparedness Framework or Google DeepMind's Frontier Safety Framework; independent trackers (e.g. SaferAI Frontier Risk Management Tracker) list this as an outstanding gap in Mistral's safety governance disclosure</td>\n<td>Governance (CORRECTED &amp; VERIFIED 29 Jul 2026 — this entry previously asserted a framework had been published; verification found none exists)</td>\n</tr>\n</tbody>\n</table>"},{"h":"Cohere (incl. Cohere Labs / C4AI)","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Secure AI Frontier Model Framework</td>\n<td>Feb 2025</td>\n<td>https://cohere.com/security</td>\n<td>Enterprise/FS-oriented deployment security framework</td>\n<td>Governance</td>\n</tr>\n<tr>\n<td>Under the Radar: Enterprise-relevant safety research (e.g. \"LLMs as auto-graders\" critiques, multilingual safety – Aya)</td>\n<td>2023–2025</td>\n<td>https://cohere.com/research</td>\n<td>C4AI work on multilingual harms and evaluation reliability</td>\n<td>Evaluation validity</td>\n</tr>\n<tr>\n<td>Elo Uncovered: Robustness and Best Practices in Language Model Evaluation</td>\n<td>Nov 2023</td>\n<td>https://arxiv.org/abs/2311.17295</td>\n<td>Shows instability of Elo-style model rankings — caution for leaderboard-based model selection in FS</td>\n<td>Evaluation validity; benchmark reliability</td>\n</tr>\n</tbody>\n</table>"},{"h":"Allen Institute for AI (AI2)","html":"<table>\n<thead>\n<tr>\n<th>Title</th>\n<th>Date</th>\n<th>URL</th>\n<th>Relevance</th>\n<th>FAIAS domains</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>WildTeaming / WildJailbreak</td>\n<td>Jun 2024</td>\n<td>https://arxiv.org/abs/2406.18510</td>\n<td>Mines in-the-wild jailbreak tactics into a 262k-prompt safety training set</td>\n<td>Jailbreaks; safeguards</td>\n</tr>\n<tr>\n<td>WildGuard: Open One-stop Moderation Tools</td>\n<td>Jun 2024</td>\n<td>https://arxiv.org/abs/2406.18495</td>\n<td>Open moderation model for prompt harm/refusal/jailbreak detection</td>\n<td>Safeguards</td>\n</tr>\n<tr>\n<td>OLMo + Dolma full-transparency releases</td>\n<td>2024–2025</td>\n<td>https://allenai.org/olmo</td>\n<td>Fully open model/data enabling contamination and provenance auditing impossible with closed models</td>\n<td>Benchmark contamination; provenance</td>\n</tr>\n<tr>\n<td>RewardBench: Evaluating Reward Models</td>\n<td>Mar 2024</td>\n<td>https://arxiv.org/abs/2403.13787</td>\n<td>First systematic reward-model evaluation — reward model quality underpins RLHF assurance</td>\n<td>Reward hacking; evaluation</td>\n</tr>\n</tbody>\n</table>"}]};
